// ── Authentic quarter-tone cent values for Arabic maqamat that use neutral intervals.
// Quarter-tone ≈ 50¢.  Neutral 2nd ≈ 150¢ · Neutral 3rd ≈ 350¢ · Neutral 6th ≈ 850¢ · Neutral 7th ≈ 1050¢
// Scales NOT listed here have all-semitone intervals (no neutral notes) → 12-TET is exact.
const MAQAM_CENTS = {
  // Rast family — neutral 3rd (350¢) and neutral 7th (1050¢)
  'Rast':           [0, 200, 350, 500, 700, 900, 1050],
  'Sikah':          [0, 200, 350, 500, 700, 900, 1050],  // starts from neutral 3rd
  'Suznak':         [0, 200, 350, 500, 700, 800, 1100],  // Rast lower + Hijaz upper
  'Husseini':       [0, 150, 300, 500, 700, 800, 1050],  // neutral 2nd and 7th

  // Bayati family — neutral 2nd (150¢)
  'Bayati':         [0, 150, 300, 500, 700, 800, 1000],
  'Kurd':           [0, 100, 300, 500, 700, 800, 1000],  // pure semitone 2nd (differs from Bayati here)
  'Bayati Shuri':   [0, 150, 300, 500, 600, 800, 1000],

  // Saba family — neutral 2nd (150¢)
  'Saba':           [0, 150, 300, 400, 500, 600, 1000],
  'Saba Zemzem':    [0, 150, 300, 400, 500, 800, 1000],

  // Iraq — neutral 2nd and neutral 7th
  'Iraq':           [0, 150, 300, 500, 700, 850, 1050],

  // All others (Hijaz, Hijaz Kar, Nahawand, Nawa Athar, Nikriz, Ajam …) are pure semitone → no entry needed
};

// Which MAQAM_CENTS degrees are neutral (differ >25¢ from their nearest semitone)?
// Precomputed for the draw loop.
function neutralDegrees(scaleName) {
  const cents = MAQAM_CENTS[scaleName];
  if (!cents) return new Set();
  const neutral = new Set();
  cents.forEach((c, i) => {
    const nearest = Math.round(c / 100) * 100;
    if (Math.abs(c - nearest) > 25) neutral.add(i);
  });
  return neutral;
}

