const SEQ = {
  bpm:       120,
  rhythmKey: '16 steps',
  gate:      0.65,  // note length as fraction of step
  grid:      {},    // `${scaleIdx}_${step}` → true
  loopLen:   16,    // active loop length (≤ seqSteps())
};
let drumLoopLen = 16; // independent drum loop length

// ── WORLD BEAT CLOCK ────────────────────────────────────────────────
// epochMs:      server-time ms at which beat 0 occurred (null = stopped).
// peerEpochMs:  epoch of a currently-playing peer — used for phase-lock join.
// masterBpm:    canonical BPM agreed upon by peers (each instance scales it
//               by syncTempoRatio to get their local SEQ.bpm).
// syncTempoRatio: local tempo multiplier vs the master BPM (1, 0.5, 2, 3…)
let epochMs        = null;
let peerEpochMs    = null;
let masterBpm      = SEQ.bpm;
let syncTempoRatio = 1;

// Thin wrappers so sync calls are no-ops when server isn't configured
function syncSend(msg)  { Sync.send(msg); }
function sharedNow()    { return Sync.sharedNow(); }

// Apply a master BPM from a peer, scaled by the local ratio
function applyPeerBpm(bpm) {
  masterBpm  = bpm;
  SEQ.bpm    = Math.max(20, Math.round(bpm * syncTempoRatio));
  const sl   = document.getElementById('seq-bpm');
  const vl   = document.getElementById('seq-bpm-val');
  if (sl) sl.value        = SEQ.bpm;
  if (vl) vl.textContent  = SEQ.bpm;
  if (seqEngine.playing) seqEngine.rebase(true);
}

function seqR()       { return RHYTHMS[SEQ.rhythmKey]; }
function seqStepDur() { return 60 / SEQ.bpm / seqR().spb; }
function seqSteps()   { return seqR().steps; }

// ═══════════════════════════════════════════════════════════════════
// AUDIO ENGINE — additive synthesis, exact temperament frequencies
// ═══════════════════════════════════════════════════════════════════

class AudioEngine {
  constructor() {
    this.actx = null;
    this.master = null;
    this.reverb = null;
    this.ready = false;
    this.enabled = true;
  }

  _init() {
    if (this.ready) return;
    this.actx = new (window.AudioContext || window.webkitAudioContext)();

    // Independent input buses (volume control per source)
    this.melodyBus = this.actx.createGain(); this.melodyBus.gain.value = 1.0;
    this.drumBus   = this.actx.createGain(); this.drumBus.gain.value   = 1.0;

    // Main mix bus → filter → kill switch (melody only)
    this.master = this.actx.createGain(); this.master.gain.value = 0.55;
    this.melodyBus.connect(this.master);
    // drumBus bypasses melody filters — routed directly after comp (see below)

    this.filter = this.actx.createBiquadFilter();
    this.filter.type = 'lowpass';
    this.filter.frequency.value = SYNTH.filterFreq;
    this.filter.Q.value = SYNTH.filterQ;

    this.kill = this.actx.createGain(); this.kill.gain.value = 1;

    const comp = this.actx.createDynamicsCompressor();
    comp.threshold.value = -10; comp.ratio.value = 5;
    comp.attack.value = 0.002;  comp.release.value = 0.08;

    // Global resonant filter (Moog/MS-20 style) — sits after comp, before output
    this.globalFilter = this.actx.createBiquadFilter();
    this.globalFilter.type = 'lowpass';
    this.globalFilter.frequency.value = 20000; // open by default
    this.globalFilter.Q.value = 0.7;

    // Distortion (parallel send from kill)
    this.distNode = this.actx.createWaveShaper();
    this.distNode.oversample = '4x';
    this.distNode.curve = this._makeDistCurve(0);
    this.distWet = this.actx.createGain(); this.distWet.gain.value = 0;

    // Delay with feedback (parallel send from kill)
    this.delayNode = this.actx.createDelay(2.0);
    this.delayNode.delayTime.value = 0.25;
    this.delayFeedback = this.actx.createGain(); this.delayFeedback.gain.value = 0.30;
    this.delayWet = this.actx.createGain(); this.delayWet.gain.value = 0;

    // Reverb
    this.reverb = this._makeReverb(2.2, 2.8);
    this.revSend = this.actx.createGain(); this.revSend.gain.value = 0.10;

    // Drum bus — separate compressor, bypasses synth EQ and global filter
    this.drumComp = this.actx.createDynamicsCompressor();
    this.drumComp.threshold.value = -12; this.drumComp.ratio.value = 4;
    this.drumComp.attack.value = 0.003; this.drumComp.release.value = 0.1;
    this.drumBus.connect(this.drumComp);
    this.drumComp.connect(this.actx.destination);

    // Main chain: master → synthFilter → kill → comp → globalFilter → destination
    this.master.connect(this.filter);
    this.filter.connect(this.kill);
    this.kill.connect(comp);
    comp.connect(this.globalFilter);
    this.globalFilter.connect(this.actx.destination);
    // Distortion chain
    this.kill.connect(this.distNode);
    this.distNode.connect(this.distWet);
    this.distWet.connect(comp);
    // Delay chain
    this.kill.connect(this.delayNode);
    this.delayNode.connect(this.delayFeedback);
    this.delayFeedback.connect(this.delayNode);
    this.delayNode.connect(this.delayWet);
    this.delayWet.connect(comp);
    // Reverb chain — also through globalFilter so sweep affects reverb tail
    this.kill.connect(this.revSend);
    this.revSend.connect(this.reverb);
    this.reverb.connect(this.globalFilter);

    this.ready = true;
  }

  _makeDistCurve(amount) {
    const n = 256, curve = new Float32Array(n);
    for (let i = 0; i < n; i++) {
      const x = (i * 2) / n - 1;
      curve[i] = amount > 0
        ? ((Math.PI + amount) * x) / (Math.PI + amount * Math.abs(x))
        : x;
    }
    return curve;
  }

  applyDistortion(amount) {
    if (!this.ready) return;
    this.distNode.curve = this._makeDistCurve(amount * 400);
  }

  _makeReverb(dur, decay) {
    const sr = this.actx.sampleRate;
    const len = Math.floor(sr * dur);
    const buf = this.actx.createBuffer(2, len, sr);
    for (let ch = 0; ch < 2; ch++) {
      const d = buf.getChannelData(ch);
      for (let i = 0; i < len; i++)
        d[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / len, decay);
    }
    const cv = this.actx.createConvolver();
    cv.buffer = buf;
    return cv;
  }

  // Precise frequency: root semitone + scale degree in chosen temperament
  // C4 = 261.626 Hz (MIDI 60), A4 = 440 Hz (MIDI 69)
  degreeFreq(rootSemitone, degree, tempKey, octave = 4) {
    const C4 = 261.62556;
    // Root in equal temperament (anchors to concert pitch)
    const rootHz = C4 * Math.pow(2, rootSemitone / 12);
    // Apply temperament cents for this scale degree
    const cents = TEMPERAMENTS[tempKey].cents[degree % 12];
    const octShift = Math.floor(degree / 12);
    return rootHz * Math.pow(2, cents / 1200 + octShift + (octave - 4));
  }

  // For fretboard: MIDI note → tempered frequency
  // Adjusts equal-tempered MIDI frequency by the temperament deviation for that degree
  midiFreq(midiNote, rootSemitone, tempKey) {
    const eqHz = 440 * Math.pow(2, (midiNote - 69) / 12);
    const degree = ((midiNote - rootSemitone) % 12 + 12) % 12;
    const deviation = TEMPERAMENTS[tempKey].cents[degree] - degree * 100;
    return eqHz * Math.pow(2, deviation / 1200);
  }

  // Additive synthesis with SYNTH-controlled ADSR, harmonics, filter, vibrato
  _playHz(hz, startOffset, duration, velocity = 0.75) {
    if (!this.ready || !this.enabled) return;
    const t = this.actx.currentTime + startOffset;
    const env = this.actx.createGain();
    env.connect(this.melodyBus);

    const pk  = 0.24 * velocity;
    const atk = SYNTH.attack;
    const dec = SYNTH.decay;
    const sus = Math.max(0.001, SYNTH.sustain);
    env.gain.setValueAtTime(0, t);
    env.gain.linearRampToValueAtTime(pk, t + atk);
    env.gain.exponentialRampToValueAtTime(pk * sus, t + atk + dec);
    env.gain.setValueAtTime(pk * sus, t + Math.max(duration - 0.1, atk + 0.05));
    env.gain.exponentialRampToValueAtTime(0.00015, t + duration + 0.08);

    // ── Sample mode ──────────────────────────────────────────────────
    if (SYNTH.sourceMode === 'sample' && SYNTH.sampleBuffer) {
      const src = this.actx.createBufferSource();
      src.buffer = SYNTH.sampleBuffer;
      src.playbackRate.value = hz / SYNTH.sampleBaseFreq;
      src.detune.value = SYNTH.detune;
      src.loop = duration > 0.8;
      src.connect(env);
      src.start(t);
      src.stop(t + duration + 0.1);
      return;
    }

    // Vibrato LFO — one oscillator shared, each harmonic gets a scaled gain node
    let lfo = null;
    if (SYNTH.vibratoDepth > 0) {
      lfo = this.actx.createOscillator();
      lfo.type = 'sine';
      lfo.frequency.value = SYNTH.vibratoRate;
      lfo.start(t + atk * 0.6);
      lfo.stop(t + duration + 0.2);
    }

    if (SYNTH.waveform !== 'sine') {
      // Single-oscillator mode (triangle, square, sawtooth, custom)
      const osc = this.actx.createOscillator();
      if (SYNTH.waveform === 'custom' && SYNTH.customWave) {
        osc.setPeriodicWave(SYNTH.customWave);
      } else {
        osc.type = SYNTH.waveform;
      }
      osc.frequency.value = hz;
      osc.detune.value = SYNTH.detune;
      if (lfo) {
        const lfoG = this.actx.createGain();
        lfoG.gain.value = hz * (Math.pow(2, SYNTH.vibratoDepth / 1200) - 1);
        lfo.connect(lfoG); lfoG.connect(osc.frequency);
      }
      osc.connect(env); osc.start(t); osc.stop(t + duration + 0.1);
    } else {
      // Additive synthesis with harmonics (sine mode), limited by numHarmonics
      SYNTH.harmonics.slice(0, SYNTH.numHarmonics).forEach(([m, a, df]) => {
        const osc = this.actx.createOscillator();
        const g   = this.actx.createGain();
        osc.type = 'sine';
        osc.frequency.value = hz * m;
        osc.detune.value = SYNTH.detune;
        if (lfo) {
          const lfoG = this.actx.createGain();
          lfoG.gain.value = hz * m * (Math.pow(2, SYNTH.vibratoDepth / 1200) - 1);
          lfo.connect(lfoG); lfoG.connect(osc.frequency);
        }
        const hd = duration * df + 0.05;
        g.gain.setValueAtTime(a, t);
        g.gain.exponentialRampToValueAtTime(0.00015, t + hd);
        osc.connect(g); g.connect(env); osc.start(t); osc.stop(t + hd + 0.1);
      });
    }
  }

  // Apply filter params live (called when synth sliders change)
  applyFilter() {
    if (!this.ready) return;
    this.filter.frequency.setTargetAtTime(SYNTH.filterFreq, this.actx.currentTime, 0.015);
    this.filter.Q.setTargetAtTime(SYNTH.filterQ, this.actx.currentTime, 0.015);
  }

  _resume() {
    if (!this.ready) this._init();
    if (this.actx.state === 'suspended') this.actx.resume();
    // Restore kill switch in case stopAll() muted it
    this.kill.gain.cancelScheduledValues(this.actx.currentTime);
    this.kill.gain.setValueAtTime(1, this.actx.currentTime);
  }

  playArpeggio(freqs, noteDur = 0.55, step = 0.17) {
    if (!this.enabled) return;
    this._resume();
    freqs.forEach((f, i) => this._playHz(f, i * step, noteDur));
  }

  playChord(freqs, duration = 3.5) {
    if (!this.enabled) return;
    this._resume();
    // Slight strum: each note 18ms apart then sustained together
    freqs.forEach((f, i) => this._playHz(f, i * 0.018, duration));
  }

  playSingle(freq, duration = 0.75) {
    if (!this.enabled) return;
    this._resume();
    this._playHz(freq, 0, duration);
  }
}

const audio = new AudioEngine();

// ═══════════════════════════════════════════════════════════════════
// STATE
// ═══════════════════════════════════════════════════════════════════

const S = {
  root: 0, temp: 'equal', family: 'western', scaleName: 'Major (Ionian)',
  chordRoot: 0, chordName: '— None —',
  showCents: true, showLabels: true,
  tuning: 'Standard (EADGBE)',
  fretboardOpen: false,
  fbMode: 'both',
};

let midiActiveQuantizedMidi = null; // quantized MIDI note number currently playing

// ═══════════════════════════════════════════════════════════════════
// CANVAS HELPERS
// ═══════════════════════════════════════════════════════════════════

const canvas = document.getElementById('canvas');
const ctx = canvas.getContext('2d');
const vizPanel = document.getElementById('viz-panel');

// Stored chord polygon vertices for hit-testing
let chordPolyPx = [];

function getScale() {
  const f = SCALE_FAMILIES[S.family];
  return f ? (f.scales[S.scaleName] || []) : [];
}
function getScaleNotes() { return getScale().map(d => (d + S.root) % 12); }

function noteAngle(noteIndex, tempKey) {
  return (TEMPERAMENTS[tempKey].cents[noteIndex] / 1200) * 2 * Math.PI - Math.PI / 2;
}

function canvasXY(e) {
  const r = canvas.getBoundingClientRect();
  return {
    x: (e.clientX - r.left) * (canvas.width / r.width),
    y: (e.clientY - r.top) * (canvas.height / r.height),
  };
}

function pointInPoly(px, py, poly) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const xi = poly[i].x, yi = poly[i].y, xj = poly[j].x, yj = poly[j].y;
    if (((yi > py) !== (yj > py)) && (px < (xj - xi) * (py - yi) / (yj - yi) + xi))
      inside = !inside;
  }
  return inside;
}

// ═══════════════════════════════════════════════════════════════════
// RIPPLE ANIMATIONS
// ═══════════════════════════════════════════════════════════════════

let ripples = [];
let animRunning = false;

function addRipple(x, y, color, maxR) {
  ripples.push({ x, y, color, maxR, r: maxR * 0.1, progress: 0 });
  if (!animRunning) { animRunning = true; requestAnimationFrame(animStep); }
}

function animStep() {
  if (ripples.length === 0) { animRunning = false; draw(); return; }
  draw();
  ripples = ripples.filter(rp => {
    rp.progress += 0.045;
    if (rp.progress >= 1) return false;
    const ease = 1 - Math.pow(1 - rp.progress, 3);
    const r = rp.maxR * 0.1 + (rp.maxR * 0.9) * ease;
    const alpha = (1 - rp.progress) * 0.9;
    ctx.beginPath();
    ctx.arc(rp.x, rp.y, r, 0, Math.PI * 2);
    ctx.strokeStyle = rp.color;
    ctx.globalAlpha = alpha;
    ctx.lineWidth = 2.5;
    ctx.stroke();
    ctx.globalAlpha = 1;
    return true;
  });
  requestAnimationFrame(animStep);
}

// Angle for a SCALE note: Arabic maqamat with neutral intervals get their authentic
// quarter-tone position on the circle; everything else uses the temperament table.
function scaleNoteAngle(scaleIdx, noteIdx, tempKey) {
  if (S.family === 'arabic' && MAQAM_CENTS[S.scaleName]) {
    const c = MAQAM_CENTS[S.scaleName][scaleIdx];
    return (c / 1200) * 2 * Math.PI - Math.PI / 2;
  }
  return noteAngle(noteIdx, tempKey);
}

// Inner zone fraction: chord polygon lives here, used by draw + click handler
const CHORD_ZONE = 0.58;

// ═══════════════════════════════════════════════════════════════════
// DRAW — main canvas
// ═══════════════════════════════════════════════════════════════════

function draw() {
  const W = canvas.width, H = canvas.height;
  if (W < 110 || H < 110) { ctx.clearRect(0, 0, W, H); return; }
  const cx = W / 2, cy = H / 2;
  const R = Math.min(W, H) * 0.355;
  const labelR = R + 22;
  const centsR = R + 40;
  const temp = S.temp;
  const tempData = TEMPERAMENTS[temp];
  const scale = getScale();
  const scaleNotes = getScaleNotes();
  const chord = CHORDS[S.chordName];
  const chordNotes = chord ? chord.map(d => (d % 12 + S.chordRoot) % 12) : [];

  ctx.clearRect(0, 0, W, H);

  // Background glow
  const bg = ctx.createRadialGradient(cx, cy, 0, cx, cy, R * 1.5);
  bg.addColorStop(0, 'rgba(55,25,110,0.13)');
  bg.addColorStop(0.6, 'rgba(20,10,50,0.06)');
  bg.addColorStop(1, 'transparent');
  ctx.beginPath(); ctx.arc(cx, cy, R * 1.5, 0, Math.PI * 2);
  ctx.fillStyle = bg; ctx.fill();

  // Outer ring
  ctx.beginPath(); ctx.arc(cx, cy, R, 0, Math.PI * 2);
  ctx.strokeStyle = 'rgba(255,255,255,0.07)'; ctx.lineWidth = 1.5; ctx.stroke();

  // Inner ring
  ctx.beginPath(); ctx.arc(cx, cy, R * 0.1, 0, Math.PI * 2);
  ctx.strokeStyle = 'rgba(255,255,255,0.05)'; ctx.lineWidth = 1; ctx.stroke();

  // Chord click zone indicator — dashed circle at CHORD_ZONE radius
  if (chord) {
    ctx.beginPath(); ctx.arc(cx, cy, R * CHORD_ZONE, 0, Math.PI * 2);
    ctx.strokeStyle = 'rgba(52,211,153,0.18)';
    ctx.lineWidth = 1;
    ctx.setLineDash([4, 5]);
    ctx.stroke();
    ctx.setLineDash([]);
  }

  // Quarter-tone tick ring — shown when Arabic family is active
  if (S.family === 'arabic') {
    for (let q = 0; q < 24; q++) {
      const a = (q / 24) * 2 * Math.PI - Math.PI / 2;
      const isFullSemi = q % 2 === 0;
      const r0 = isFullSemi ? R * 0.95 : R * 0.975;
      ctx.beginPath();
      ctx.moveTo(cx + r0 * Math.cos(a), cy + r0 * Math.sin(a));
      ctx.lineTo(cx + R * Math.cos(a), cy + R * Math.sin(a));
      ctx.strokeStyle = isFullSemi ? 'rgba(255,255,255,0.12)' : 'rgba(245,158,11,0.28)';
      ctx.lineWidth = isFullSemi ? 1 : 0.8;
      ctx.stroke();
    }
  }

  // Spokes (12 standard semitones)
  for (let i = 0; i < 12; i++) {
    const a = noteAngle(i, temp);
    ctx.beginPath();
    ctx.moveTo(cx + R * 0.11 * Math.cos(a), cy + R * 0.11 * Math.sin(a));
    ctx.lineTo(cx + R * (S.family === 'arabic' ? 0.94 : 1.0) * Math.cos(a),
               cy + R * (S.family === 'arabic' ? 0.94 : 1.0) * Math.sin(a));
    ctx.strokeStyle = 'rgba(255,255,255,0.035)'; ctx.lineWidth = 1; ctx.stroke();
  }

  // Precompute: authentic angle per scale degree (uses MAQAM_CENTS when applicable)
  const scaleAngles = scale.map((deg, si) => scaleNoteAngle(si, scaleNotes[si], temp));
  const neutralSet = (S.family === 'arabic') ? neutralDegrees(S.scaleName) : new Set();

  // Scale polygon — vertices at authentic quarter-tone positions
  if (scaleNotes.length > 1) {
    ctx.beginPath();
    scaleNotes.forEach((n, i) => {
      const a = scaleAngles[i];
      const x = cx + R * Math.cos(a), y = cy + R * Math.sin(a);
      i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
    });
    ctx.closePath();
    ctx.strokeStyle = 'rgba(167,139,250,0.52)'; ctx.lineWidth = 1.5; ctx.setLineDash([]); ctx.stroke();
    ctx.fillStyle = 'rgba(167,139,250,0.055)'; ctx.fill();
  }

  // Chord polygon — stored for hit-testing
  chordPolyPx = [];
  if (chord && chordNotes.length > 1) {
    const chordR = R * 0.83;
    chordNotes.forEach(n => {
      const a = noteAngle(n, temp);
      chordPolyPx.push({ x: cx + chordR * Math.cos(a), y: cy + chordR * Math.sin(a) });
    });
    ctx.beginPath();
    chordPolyPx.forEach(({ x, y }, i) => i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y));
    ctx.closePath();
    ctx.strokeStyle = 'rgba(52,211,153,0.85)'; ctx.lineWidth = 2.2; ctx.setLineDash([]); ctx.stroke();
    ctx.fillStyle = 'rgba(52,211,153,0.07)'; ctx.fill();

    // Chord glow vertices
    chordPolyPx.forEach(({ x, y }) => {
      const g = ctx.createRadialGradient(x, y, 0, x, y, 9);
      g.addColorStop(0, 'rgba(52,211,153,0.85)'); g.addColorStop(1, 'transparent');
      ctx.beginPath(); ctx.arc(x, y, 9, 0, Math.PI * 2); ctx.fillStyle = g; ctx.fill();
      ctx.beginPath(); ctx.arc(x, y, 4, 0, Math.PI * 2); ctx.fillStyle = '#34d399'; ctx.fill();
    });
  }

  // 12 standard chromatic dots (non-scale notes at semitone positions)
  for (let i = 0; i < 12; i++) {
    if (scaleNotes.includes(i)) continue; // scale notes drawn separately below
    const a = noteAngle(i, temp);
    const x = cx + R * Math.cos(a), y = cy + R * Math.sin(a);
    const inChord = chordNotes.includes(i);
    ctx.beginPath(); ctx.arc(x, y, inChord ? 5.5 : 4, 0, Math.PI * 2);
    let fillStyle = 'rgba(255,255,255,0.13)';
    if (inChord) {
      const interval = (i - S.chordRoot + 12) % 12;
      if (interval === 0) fillStyle = 'rgba(239,68,68,0.7)';
      else if (interval === 3 || interval === 4) fillStyle = 'rgba(234,179,8,0.7)';
      else if (interval === 6 || interval === 7 || interval === 8) fillStyle = 'rgba(59,130,246,0.7)';
      else if (interval === 10 || interval === 11) fillStyle = 'rgba(16,185,129,0.7)';
      else fillStyle = 'rgba(168,85,247,0.7)';
    }
    ctx.fillStyle = fillStyle; ctx.fill();
    if (S.showLabels) {
      ctx.font = '10px system-ui'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      ctx.fillStyle = 'rgba(255,255,255,0.2)';
      ctx.fillText(CHROMATIC[i], cx + labelR * Math.cos(a), cy + labelR * Math.sin(a));
    }
  }

  // Scale notes — drawn at authentic quarter-tone positions when Arabic family
  scaleNotes.forEach((noteIdx, si) => {
    const a = scaleAngles[si];   // authentic angle (may be between semitones)
    const x = cx + R * Math.cos(a), y = cy + R * Math.sin(a);
    const isRoot   = noteIdx === S.root;
    const inChord  = chordNotes.includes(noteIdx);
    const isNeutral = neutralSet.has(si);
    const dotR = isRoot ? 10 : 8;

    let col, glowCol, glowR;
    if (inChord) {
      const interval = (noteIdx - S.chordRoot + 12) % 12;
      if (interval === 0)      { col = '#ef4444'; glowCol = 'rgba(239,68,68,0.45)'; }
      else if (interval === 3 || interval === 4) { col = '#eab308'; glowCol = 'rgba(234,179,8,0.45)'; }
      else if (interval === 6 || interval === 7 || interval === 8) { col = '#3b82f6'; glowCol = 'rgba(59,130,246,0.45)'; }
      else if (interval === 10 || interval === 11) { col = '#10b981'; glowCol = 'rgba(16,185,129,0.45)'; }
      else                     { col = '#a855f7'; glowCol = 'rgba(168,85,247,0.45)'; }
      glowR = 13;
    } else if (isRoot) {
      col = '#f59e0b'; glowCol = 'rgba(245,158,11,0.45)'; glowR = 15;
    } else {
      col = '#a78bfa'; glowCol = 'rgba(167,139,250,0.32)'; glowR = 12;
    }

    const g = ctx.createRadialGradient(x, y, dotR, x, y, glowR);
    g.addColorStop(0, glowCol); g.addColorStop(1, 'transparent');
    ctx.beginPath(); ctx.arc(x, y, glowR, 0, Math.PI * 2); ctx.fillStyle = g; ctx.fill();

    ctx.beginPath(); ctx.arc(x, y, dotR, 0, Math.PI * 2); ctx.fillStyle = col; ctx.fill();

    if (isRoot) {
      ctx.beginPath(); ctx.arc(x, y, dotR + 3.5, 0, Math.PI * 2);
      ctx.strokeStyle = 'rgba(245,158,11,0.55)'; ctx.lineWidth = 1.5; ctx.setLineDash([3,2]); ctx.stroke(); ctx.setLineDash([]);
    }

    // Neutral note ring — amber dashed ring to signal quarter-tone
    if (isNeutral) {
      ctx.beginPath(); ctx.arc(x, y, dotR + 4.5, 0, Math.PI * 2);
      ctx.strokeStyle = 'rgba(245,158,11,0.55)'; ctx.lineWidth = 1; ctx.setLineDash([2,2]); ctx.stroke(); ctx.setLineDash([]);
    }

    if (S.showLabels) {
      const lx = cx + labelR * Math.cos(a), ly = cy + labelR * Math.sin(a);
      ctx.font = 'bold 11px system-ui'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      ctx.fillStyle = isRoot ? '#f59e0b' : '#ddd8ff';
      ctx.fillText(CHROMATIC[noteIdx], lx, ly);
      // Quarter-tone marker next to label
      if (isNeutral) {
        ctx.font = '8px system-ui'; ctx.fillStyle = 'rgba(245,158,11,0.75)';
        ctx.fillText('½♭', lx + 12, ly - 5);
      }
    }

    // Cent annotation: Arabic → show maqam cents; others → show temperament deviation
    if (S.showCents) {
      const lx = cx + centsR * Math.cos(a), ly = cy + centsR * Math.sin(a);
      ctx.font = '8.5px system-ui'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      if (S.family === 'arabic' && MAQAM_CENTS[S.scaleName]) {
        const mCents = MAQAM_CENTS[S.scaleName][si];
        ctx.fillStyle = isNeutral ? 'rgba(245,158,11,0.8)' : 'rgba(255,255,255,0.3)';
        ctx.fillText(mCents + '¢', lx, ly);
      } else if (temp !== 'equal') {
        const deg = scale[si];
        const dev = tempData.cents[deg] - deg * 100;
        if (Math.abs(dev) > 0.4) {
          ctx.fillStyle = dev > 0 ? 'rgba(96,165,250,0.75)' : 'rgba(252,165,165,0.75)';
          ctx.fillText((dev > 0 ? '+' : '') + dev.toFixed(1) + '¢', lx, ly);
        }
      }
    }
  });

  // MIDI active note highlight ring
  if (midiActiveQuantizedMidi !== null) {
    const _mpc = (midiActiveQuantizedMidi % 12 + 12) % 12;
    scaleNotes.forEach((noteIdx, si) => {
      if (noteIdx !== _mpc) return;
      const a = scaleAngles[si];
      const x = cx + R * Math.cos(a), y = cy + R * Math.sin(a);
      ctx.beginPath(); ctx.arc(x, y, 16, 0, Math.PI * 2);
      ctx.strokeStyle = 'rgba(255,255,255,0.9)';
      ctx.lineWidth = 3; ctx.setLineDash([]); ctx.stroke();
      const pg = ctx.createRadialGradient(x, y, 0, x, y, 22);
      pg.addColorStop(0, 'rgba(255,255,255,0.15)'); pg.addColorStop(1, 'transparent');
      ctx.beginPath(); ctx.arc(x, y, 22, 0, Math.PI * 2); ctx.fillStyle = pg; ctx.fill();
    });
  }

  // Sequencer active note highlight — sky-blue ring per active step note
  if (seqEngine.playing && seqEngine.displayStep >= 0) {
    const step = seqEngine.displayStep;
    for (let si = 0; si < scale.length; si++) {
      if (!SEQ.grid[`${si}_${step}`]) continue;
      if (si >= scaleAngles.length) continue;
      const a = scaleAngles[si];
      const x = cx + R * Math.cos(a), y = cy + R * Math.sin(a);
      ctx.beginPath(); ctx.arc(x, y, 19, 0, Math.PI * 2);
      ctx.strokeStyle = 'rgba(56,189,248,0.92)';
      ctx.lineWidth = 2.5; ctx.setLineDash([]); ctx.stroke();
      const pg = ctx.createRadialGradient(x, y, 0, x, y, 30);
      pg.addColorStop(0, 'rgba(56,189,248,0.32)'); pg.addColorStop(1, 'transparent');
      ctx.beginPath(); ctx.arc(x, y, 30, 0, Math.PI * 2); ctx.fillStyle = pg; ctx.fill();
    }
  }

  // Center labels
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.font = 'bold 19px system-ui'; ctx.fillStyle = '#f59e0b';
  ctx.fillText(CHROMATIC[S.root], cx, cy - 9);
  ctx.font = '9.5px system-ui'; ctx.fillStyle = 'rgba(255,255,255,0.32)';
  ctx.fillText(S.scaleName.replace(/\s*\(.*\)/, '').trim(), cx, cy + 9);
  if (S.chordName !== '— None —') {
    ctx.font = '8.5px system-ui'; ctx.fillStyle = 'rgba(52,211,153,0.55)';
    ctx.fillText(CHROMATIC[S.chordRoot] + ' ' + S.chordName, cx, cy + 23);
  }
  if (document.getElementById('seq-wrap').classList.contains('open')) drawSequencer();
}

// ═══════════════════════════════════════════════════════════════════
// CANVAS INTERACTION
// ═══════════════════════════════════════════════════════════════════

function getScaleFreqs() {
  const C4 = 261.62556;
  const rootHz = C4 * Math.pow(2, S.root / 12); // concert-pitch anchor

  // Arabic maqamat with neutral intervals: use authentic quarter-tone cents directly
  if (S.family === 'arabic' && MAQAM_CENTS[S.scaleName]) {
    const cents = MAQAM_CENTS[S.scaleName];
    const freqs = cents.map(c => rootHz * Math.pow(2, c / 1200));
    freqs.push(rootHz * 2); // octave
    return freqs;
  }

  // All other families: use temperament table
  const scale = getScale();
  const freqs = scale.map(d => audio.degreeFreq(S.root, d, S.temp, 4));
  freqs.push(audio.degreeFreq(S.root, 0, S.temp, 5));
  return freqs;
}

function getChordFreqs() {
  const chord = CHORDS[S.chordName];
  if (!chord || chord.length === 0) return [];
  // d % 12 gives the scale degree; Math.floor(d/12) handles 9ths voiced above the octave
  return chord.map(d => audio.degreeFreq(S.chordRoot, d % 12, S.temp, 4 + Math.floor(d / 12)));
}

function playChordNow() {
  if (seqEngine.playing) return;
  const freqs = getChordFreqs();
  if (!freqs.length) return;
  audio.playChord(freqs);
  const W = canvas.width, H = canvas.height;
  addRipple(W / 2, H / 2, 'rgba(52,211,153,0.75)', Math.min(W, H) * 0.355 * 0.58);
}

canvas.addEventListener('click', e => {
  if (seqEngine.playing) return;
  const { x, y } = canvasXY(e);
  const W = canvas.width, H = canvas.height;
  const cx = W / 2, cy = H / 2;
  const R = Math.min(W, H) * 0.355;
  const dist = Math.hypot(x - cx, y - cy);

  if (dist > R * 1.15) return;

  const chordActive = CHORDS[S.chordName] !== null;
  // Inner zone → chord; outer ring → scale arpeggio
  if (chordActive && dist < R * CHORD_ZONE) {
    playChordNow();
  } else {
    audio.playArpeggio(getScaleFreqs());
    addRipple(cx, cy, 'rgba(167,139,250,0.65)', R);
  }
});

canvas.addEventListener('mousemove', e => {
  const { x, y } = canvasXY(e);
  const cx = canvas.width / 2, cy = canvas.height / 2;
  const R = Math.min(canvas.width, canvas.height) * 0.355;
  const dist = Math.hypot(x - cx, y - cy);
  const chordActive = CHORDS[S.chordName] !== null;
  if (dist > R * 1.15) { canvas.style.cursor = 'default'; canvas.title = ''; return; }
  canvas.style.cursor = 'pointer';
  canvas.title = (chordActive && dist < R * CHORD_ZONE) ? 'Click · play chord' : 'Click · play arpeggio';
});

// ═══════════════════════════════════════════════════════════════════
// GUITAR FRETBOARD
// ═══════════════════════════════════════════════════════════════════

const fbCanvas = document.getElementById('fb-canvas');
const fbCtx = fbCanvas.getContext('2d');

const NUM_FRETS = 14;
const STRING_NAMES_TOP = ['e','B','G','D','A','E']; // high to low visually

let chordPositionBoxes = [];
function updateChordPositions() {
  if (S.chordName === '— None —' || !CHORDS[S.chordName]) {
    chordPositionBoxes = [];
    S.fbPosFilter = -1;
    return;
  }

  const root = S.chordRoot;
  const chordNotesSet = new Set(CHORDS[S.chordName].map(d => (d + root) % 12));

  // openStrings[0] = high e (MIDI 64), openStrings[5] = low E (MIDI 40) for standard
  const openStrings = [...GUITAR_TUNINGS[S.tuning]].reverse();

  const SPAN = 3;
  const seenSigs = new Set();
  const allVoicings = [];

  for (let wMin = 0; wMin <= NUM_FRETS - SPAN; wMin++) {
    const wMax = wMin + SPAN;

    // Open strings only allowed in low positions — above fret 2 they'd mix with fretted notes
    // and beat real in-window voicings on score without representing an actual hand position.
    const allowOpen = wMin <= 2;

    // For each string: null = mute, 0 = open (if chord tone and allowed), 1..wMax = fretted chord tones
    const candidates = openStrings.map(oMidi => {
      const opts = [null];
      if (allowOpen && chordNotesSet.has(oMidi % 12)) opts.push(0);
      for (let f = Math.max(1, wMin); f <= wMax; f++) {
        if (chordNotesSet.has((oMidi + f) % 12)) opts.push(f);
      }
      return opts;
    });

    let windowBest = null;
    let windowBestScore = -Infinity;

    const backtrack = (s, current, notes) => {
      if (s === 6) {
        if (notes.size < chordNotesSet.size) return;

        const played = current.filter(f => f !== null);
        if (played.length < 3) return;

        // Find lowest-pitch (highest index) and highest-pitch (lowest index) played strings
        let loStr = -1, hiStr = -1;
        for (let i = 5; i >= 0; i--) { if (current[i] !== null && loStr === -1) loStr = i; }
        for (let i = 0; i < 6; i++) { if (current[i] !== null && hiStr === -1) hiStr = i; }

        let innerMutes = 0;
        for (let i = hiStr; i <= loStr; i++) { if (current[i] === null) innerMutes++; }

        const bassNote = (openStrings[loStr] + current[loStr]) % 12;
        const fretted = played.filter(f => f > 0);
        const span = fretted.length > 0 ? Math.max(...fretted) - Math.min(...fretted) : 0;

        const score = played.length * 10
          + (bassNote === root ? 50 : 0)
          - innerMutes * 20
          - span * 6;

        if (score > windowBestScore) {
          windowBestScore = score;
          windowBest = { frets: [...current], score, min: wMin, max: wMax };
        }
        return;
      }

      for (const f of candidates[s]) {
        current.push(f);
        const newNotes = new Set(notes);
        if (f !== null) newNotes.add((openStrings[s] + f) % 12);
        backtrack(s + 1, current, newNotes);
        current.pop();
      }
    };

    backtrack(0, [], new Set());

    if (windowBest) {
      const sig = windowBest.frets.join(',');
      if (!seenSigs.has(sig)) {
        seenSigs.add(sig);
        allVoicings.push(windowBest);
      }
    }
  }

  chordPositionBoxes = allVoicings.sort((a, b) => {
    const avg = v => v.frets.filter(f => f !== null).reduce((s, f) => s + f, 0) / v.frets.filter(f => f !== null).length;
    return avg(a) - avg(b);
  });
}

function drawFretboard() {
  updateChordPositions();
  const posCtrl = document.getElementById('fb-pos-controls');
  if (posCtrl) {
    const hasChord = S.chordName !== '— None —' && S.fbMode !== 'scale' && chordPositionBoxes.length > 0;
    posCtrl.style.display = 'flex';
    const lbl = document.getElementById('fb-pos-lbl');
    const btnPrev = document.getElementById('btn-fb-pos-prev');
    const btnNext = document.getElementById('btn-fb-pos-next');
    if (!hasChord) {
      S.fbPosFilter = -1;
      if (lbl) lbl.innerText = '—';
      if (btnPrev) btnPrev.disabled = true;
      if (btnNext) btnNext.disabled = true;
    } else {
      if (S.fbPosFilter >= chordPositionBoxes.length) S.fbPosFilter = -1;
      if (lbl) lbl.innerText = S.fbPosFilter === -1 ? `All (${chordPositionBoxes.length})` : `${S.fbPosFilter + 1} / ${chordPositionBoxes.length}`;
      if (btnPrev) btnPrev.disabled = false;
      if (btnNext) btnNext.disabled = false;
    }
  }

  const wrap = fbCanvas.parentElement;
  const DPR = window.devicePixelRatio || 1;
  const W = wrap.clientWidth, H = wrap.clientHeight;
  fbCanvas.width = W * DPR;
  fbCanvas.height = H * DPR;
  fbCanvas.style.width = W + 'px';
  fbCanvas.style.height = H + 'px';
  fbCtx.scale(DPR, DPR);

  const openStrings = [...GUITAR_TUNINGS[S.tuning]].reverse(); // high e to low E
  const margin = { left: 28, right: 14, top: 16, bottom: 16 };
  const fretW = (W - margin.left - margin.right) / NUM_FRETS;
  const totalStrings = 6;
  const stringSpacing = (H - margin.top - margin.bottom) / (totalStrings - 1);

  const scaleNotes = getScaleNotes();
  const chord = CHORDS[S.chordName];
  const chordNotes = chord ? chord.map(d => (d % 12 + S.chordRoot) % 12) : [];

  // Fretboard background
  const fbGrad = fbCtx.createLinearGradient(0, 0, 0, H);
  fbGrad.addColorStop(0, '#2a1505');
  fbGrad.addColorStop(0.5, '#1e0e03');
  fbGrad.addColorStop(1, '#160b02');
  fbCtx.fillStyle = fbGrad;
  fbCtx.fillRect(margin.left, margin.top - 6, W - margin.left - margin.right, H - margin.top - margin.bottom + 12);

  // Fret markers (dots at 3,5,7,9,12)
  const dotFrets = [3,5,7,9,12];
  dotFrets.forEach(f => {
    if (f > NUM_FRETS) return;
    const fretAbsolute = f;
    const xLeft = margin.left + (fretAbsolute - 1) * fretW;
    const xMid = xLeft + fretW / 2;
    const yMid = margin.top + (H - margin.top - margin.bottom) / 2;
    if (f === 12) {
      // Double dot
      [-1, 1].forEach(dir => {
        fbCtx.beginPath();
        fbCtx.arc(xMid, yMid + dir * stringSpacing, 4.5, 0, Math.PI * 2);
        fbCtx.fillStyle = 'rgba(255,255,255,0.08)';
        fbCtx.fill();
      });
    } else {
      fbCtx.beginPath();
      fbCtx.arc(xMid, yMid, 4.5, 0, Math.PI * 2);
      fbCtx.fillStyle = 'rgba(255,255,255,0.08)';
      fbCtx.fill();
    }
  });

  // Fret lines
  for (let f = 0; f <= NUM_FRETS; f++) {
    const x = margin.left + f * fretW;
    fbCtx.beginPath();
    fbCtx.moveTo(x, margin.top - 4);
    fbCtx.lineTo(x, margin.top + stringSpacing * (totalStrings - 1) + 4);
    if (f === 0) {
      // Nut
      fbCtx.strokeStyle = 'rgba(220,210,190,0.7)';
      fbCtx.lineWidth = 4;
    } else {
      fbCtx.strokeStyle = 'rgba(160,140,100,0.25)';
      fbCtx.lineWidth = 1;
    }
    fbCtx.stroke();
  }

  // Strings
  for (let s = 0; s < totalStrings; s++) {
    const y = margin.top + s * stringSpacing;
    const thickness = 0.8 + s * 0.28;
    fbCtx.beginPath();
    fbCtx.moveTo(margin.left, y);
    fbCtx.lineTo(margin.left + NUM_FRETS * fretW, y);
    fbCtx.strokeStyle = `rgba(210,195,160,${0.35 + s * 0.04})`;
    fbCtx.lineWidth = thickness;
    fbCtx.stroke();
  }

  // String name labels (left)
  STRING_NAMES_TOP.forEach((name, s) => {
    const y = margin.top + s * stringSpacing;
    fbCtx.font = '9px system-ui';
    fbCtx.textAlign = 'center';
    fbCtx.textBaseline = 'middle';
    fbCtx.fillStyle = 'rgba(255,255,255,0.35)';
    fbCtx.fillText(name, margin.left - 14, y);
  });

  // Fret numbers (top)
  for (let f = 1; f <= NUM_FRETS; f++) {
    const x = margin.left + (f - 0.5) * fretW;
    fbCtx.font = '8px system-ui';
    fbCtx.textAlign = 'center';
    fbCtx.textBaseline = 'middle';
    fbCtx.fillStyle = 'rgba(255,255,255,0.18)';
    fbCtx.fillText(String(f), x, margin.top - 8);
  }

  // Note dots on frets
  for (let s = 0; s < totalStrings; s++) {
    const openMidi = openStrings[s];
    const sy = margin.top + s * stringSpacing;

    for (let f = 0; f <= NUM_FRETS; f++) {
      const midi = openMidi + f;
      const noteIdx = midi % 12;
      const inScale = scaleNotes.includes(noteIdx);
      const isRoot = noteIdx === S.root;
      const inChord = chordNotes.includes(noteIdx);
      const isMidiActive = midiActiveQuantizedMidi !== null && midi === midiActiveQuantizedMidi;

      let drawScl = inScale;
      let drawChd = inChord;
      let drawRt = isRoot;
      if (S.fbMode === 'scale') { drawChd = false; }
      else if (S.fbMode === 'chord') { drawScl = false; drawRt = false; }

      if (!drawScl && !drawChd && !isMidiActive && !drawRt) continue;

      const x = f === 0
        ? margin.left - fretW * 0.35
        : margin.left + (f - 0.5) * fretW;

      let alpha = 1.0;
      if (S.fbPosFilter !== -1 && chordPositionBoxes.length > 0 && S.chordName !== '— None —') {
        const activeBox = chordPositionBoxes[S.fbPosFilter];
        if (activeBox.frets[s] !== f) {
           alpha = 0.15;
        }
      }

      let dotColor, border;
      if (drawChd) {
        const interval = (noteIdx - S.chordRoot + 12) % 12;
        if (interval === 0) {
          dotColor = inScale ? '#ef4444' : 'rgba(239,68,68,0.65)';
          border = 'rgba(239,68,68,0.5)';
        } else if (interval === 3 || interval === 4) {
          dotColor = inScale ? '#eab308' : 'rgba(234,179,8,0.65)';
          border = 'rgba(234,179,8,0.5)';
        } else if (interval === 6 || interval === 7 || interval === 8) {
          dotColor = inScale ? '#3b82f6' : 'rgba(59,130,246,0.65)';
          border = 'rgba(59,130,246,0.5)';
        } else if (interval === 10 || interval === 11) {
          dotColor = inScale ? '#10b981' : 'rgba(16,185,129,0.65)';
          border = 'rgba(16,185,129,0.5)';
        } else {
          dotColor = inScale ? '#a855f7' : 'rgba(168,85,247,0.65)';
          border = 'rgba(168,85,247,0.5)';
        }
      } else if (drawRt) {
        dotColor = '#f59e0b'; border = 'rgba(245,158,11,0.6)';
      } else {
        dotColor = '#a78bfa'; border = 'rgba(167,139,250,0.4)';
      }

      fbCtx.globalAlpha = alpha;

      fbCtx.beginPath();
      fbCtx.arc(x, sy, 7, 0, Math.PI * 2);
      fbCtx.fillStyle = dotColor;
      fbCtx.fill();
      fbCtx.strokeStyle = border;
      fbCtx.lineWidth = 1.5;
      fbCtx.stroke();

      fbCtx.font = 'bold 7px system-ui';
      fbCtx.textAlign = 'center';
      fbCtx.textBaseline = 'middle';
      fbCtx.fillStyle = drawRt ? '#1a0c00' : 'rgba(0,0,0,0.75)';
      fbCtx.fillText(CHROMATIC[noteIdx], x, sy);

      // MIDI playback highlight ring
      if (isMidiActive) {
        fbCtx.beginPath(); fbCtx.arc(x, sy, 11, 0, Math.PI * 2);
        fbCtx.strokeStyle = 'rgba(255,255,255,0.92)'; fbCtx.lineWidth = 2.5; fbCtx.stroke();
        const pg = fbCtx.createRadialGradient(x, sy, 0, x, sy, 16);
        pg.addColorStop(0, 'rgba(255,255,255,0.18)'); pg.addColorStop(1, 'transparent');
        fbCtx.beginPath(); fbCtx.arc(x, sy, 16, 0, Math.PI * 2); fbCtx.fillStyle = pg; fbCtx.fill();
      }

      fbCtx.globalAlpha = 1.0;
    }
  }

  // Sequencer active note highlights — supports microtonal virtual fret positions
  if (seqEngine.playing) {
    const activeFreqs = getSeqActiveFreqs();
    activeFreqs.forEach(targetFreq => {
      for (let s = 0; s < totalStrings; s++) {
        const openMidi = openStrings[s];
        // Equal-temperament open string frequency (A4=440)
        const openFreq = 440 * Math.pow(2, (openMidi - 69) / 12);
        // Virtual fret: may be fractional for microtonal scales
        const vf = 12 * Math.log2(targetFreq / openFreq);
        if (vf < -0.6 || vf > NUM_FRETS + 0.5) continue;

        const vfClamped = Math.max(0, vf);
        const x = vfClamped < 0.5
          ? margin.left - fretW * 0.35          // open string
          : margin.left + (vfClamped - 0.5) * fretW;
        const sy = margin.top + s * stringSpacing;

        // Microtonal = fret position is not close to any integer fret
        const isMicrotonal = Math.abs(vf - Math.round(vf)) > 0.08;
        const ringColor = isMicrotonal ? 'rgba(245,158,11,0.95)' : 'rgba(52,211,153,0.95)';
        const glowColor = isMicrotonal ? 'rgba(245,158,11,0.18)' : 'rgba(52,211,153,0.15)';

        // Outer glow
        const pg = fbCtx.createRadialGradient(x, sy, 0, x, sy, 18);
        pg.addColorStop(0, glowColor); pg.addColorStop(1, 'transparent');
        fbCtx.beginPath(); fbCtx.arc(x, sy, 18, 0, Math.PI * 2);
        fbCtx.fillStyle = pg; fbCtx.fill();

        // Highlight ring
        fbCtx.beginPath(); fbCtx.arc(x, sy, 11, 0, Math.PI * 2);
        fbCtx.strokeStyle = ringColor; fbCtx.lineWidth = 2.5; fbCtx.stroke();

        // For microtonal: draw a small position indicator line between frets
        if (isMicrotonal) {
          fbCtx.beginPath();
          fbCtx.moveTo(x, sy - 14); fbCtx.lineTo(x, sy + 14);
          fbCtx.strokeStyle = 'rgba(245,158,11,0.55)';
          fbCtx.lineWidth = 1; fbCtx.stroke();
        }
      }
    });
  }
}

fbCanvas.addEventListener('click', e => {
  const wrap = fbCanvas.parentElement;
  const rect = fbCanvas.getBoundingClientRect();
  const DPR = window.devicePixelRatio || 1;
  const px = (e.clientX - rect.left);
  const py = (e.clientY - rect.top);
  const W = wrap.clientWidth, H = wrap.clientHeight;

  const openStrings = [...GUITAR_TUNINGS[S.tuning]].reverse();
  const margin = { left: 28, right: 14, top: 16, bottom: 16 };
  const fretW = (W - margin.left - margin.right) / NUM_FRETS;
  const stringSpacing = (H - margin.top - margin.bottom) / 5;

  // Find closest string
  let bestStr = -1, bestDist = 99;
  for (let s = 0; s < 6; s++) {
    const sy = margin.top + s * stringSpacing;
    const d = Math.abs(py - sy);
    if (d < bestDist) { bestDist = d; bestStr = s; }
  }
  if (bestDist > stringSpacing * 0.55) return;

  // Find fret
  let fret = -1;
  if (px < margin.left) { fret = 0; }
  else { fret = Math.floor((px - margin.left) / fretW) + 1; }
  if (fret < 0 || fret > NUM_FRETS) return;

  const midi = openStrings[bestStr] + fret;
  const freq = audio.midiFreq(midi, S.root, S.temp);
  if (!seqEngine.playing) audio.playSingle(freq);

  // Small ripple on fretboard
  const fx = fret === 0
    ? margin.left - fretW * 0.35
    : margin.left + (fret - 0.5) * fretW;
  const fy = margin.top + bestStr * stringSpacing;
  // Flash dot
  fbCtx.beginPath();
  fbCtx.arc(fx, fy, 12, 0, Math.PI * 2);
  fbCtx.fillStyle = 'rgba(255,255,255,0.25)';
  fbCtx.fill();
  setTimeout(drawFretboard, 120);
});

// ═══════════════════════════════════════════════════════════════════
// UI BUILDING
// ═══════════════════════════════════════════════════════════════════

function buildNoteGrid(id, stateKey) {
  const el = document.getElementById(id);
  CHROMATIC.forEach((n, i) => {
    const btn = document.createElement('button');
    btn.className = 'note-btn';
    btn.textContent = n;
    btn.addEventListener('click', () => {
      S[stateKey] = i;
      refreshNoteGrid(id, stateKey);
      updateInfo(); draw(); drawFretboard();
      // Chord root changed → replay chord; scale root changed → replay arpeggio
      if (!seqEngine.playing) {
        if (stateKey === 'chordRoot' && CHORDS[S.chordName]) playChordNow();
        if (stateKey === 'root') audio.playArpeggio(getScaleFreqs());
      }
    });
    el.appendChild(btn);
  });
  refreshNoteGrid(id, stateKey);
}

function refreshNoteGrid(id, stateKey) {
  const cls = stateKey === 'chordRoot' ? 'active-chord' : 'active';
  document.querySelectorAll(`#${id} .note-btn`).forEach((btn, i) => {
    btn.classList.remove('active', 'active-chord');
    if (S[stateKey] === i) btn.classList.add(cls);
  });
}

function buildTemperamentSelect() {
  const sel = document.getElementById('sel-temperament');
  Object.entries(TEMPERAMENTS).forEach(([k, v]) => {
    const opt = document.createElement('option');
    opt.value = k; opt.textContent = v.name;
    if (k === S.temp) opt.selected = true;
    sel.appendChild(opt);
  });
  sel.addEventListener('change', () => {
    S.temp = sel.value;
    document.getElementById('temp-desc').textContent = TEMPERAMENTS[S.temp].desc;
    const ms = document.getElementById('mob-temp-sel');
    if (ms) ms.value = S.temp;
    updateInfo(); draw(); drawFretboard();
  });
  document.getElementById('temp-desc').textContent = TEMPERAMENTS[S.temp].desc;
}

function buildFamilySelect() {
  const sel = document.getElementById('sel-family');
  Object.entries(SCALE_FAMILIES).forEach(([k, v]) => {
    const opt = document.createElement('option');
    opt.value = k; opt.textContent = v.name;
    if (k === S.family) opt.selected = true;
    sel.appendChild(opt);
  });
  sel.addEventListener('change', () => {
    S.family = sel.value;
    buildScaleSelect();
    updateInfo(); draw(); drawFretboard();
  });
}

function buildScaleSelect() {
  const sel = document.getElementById('sel-scale');
  sel.innerHTML = '';
  const f = SCALE_FAMILIES[S.family];
  if (!f) return;
  Object.keys(f.scales).forEach(name => {
    const opt = document.createElement('option');
    opt.value = name; opt.textContent = name;
    if (name === S.scaleName) opt.selected = true;
    sel.appendChild(opt);
  });
  if (!f.scales[S.scaleName]) {
    S.scaleName = Object.keys(f.scales)[0];
    sel.value = S.scaleName;
  }
}

function buildChordTypeGrid() {
  const el = document.getElementById('chord-type-grid');
  Object.keys(CHORDS).forEach(name => {
    const btn = document.createElement('button');
    btn.className = 'chord-btn' + (name === '— None —' ? ' none-btn' : '');
    btn.textContent = name;
    if (name === S.chordName) btn.classList.add('active');
    btn.addEventListener('click', () => {
      S.chordName = name;
      document.querySelectorAll('.chord-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      updateInfo(); draw(); drawFretboard();
      if (CHORDS[name] && !seqEngine.playing) playChordNow();
    });
    el.appendChild(btn);
  });
}

function buildTuningSelect() {
  const sel = document.getElementById('sel-tuning');
  Object.keys(GUITAR_TUNINGS).forEach(name => {
    const opt = document.createElement('option');
    opt.value = name; opt.textContent = name;
    if (name === S.tuning) opt.selected = true;
    sel.appendChild(opt);
  });
  sel.addEventListener('change', () => { S.tuning = sel.value; drawFretboard(); });

  const fbModeSel = document.getElementById('sel-fb-mode');
  if (fbModeSel) {
    fbModeSel.addEventListener('change', () => { S.fbMode = fbModeSel.value; drawFretboard(); });
  }

  const btnFbPrev = document.getElementById('btn-fb-pos-prev');
  if (btnFbPrev) btnFbPrev.addEventListener('click', () => {
    if (chordPositionBoxes.length === 0) return;
    S.fbPosFilter = S.fbPosFilter > -1 ? S.fbPosFilter - 1 : chordPositionBoxes.length - 1;
    drawFretboard();
  });

  const btnFbNext = document.getElementById('btn-fb-pos-next');
  if (btnFbNext) btnFbNext.addEventListener('click', () => {
    if (chordPositionBoxes.length === 0) return;
    S.fbPosFilter = S.fbPosFilter < chordPositionBoxes.length - 1 ? S.fbPosFilter + 1 : -1;
    drawFretboard();
  });
}


function updateInfo() {
  const scale = getScale();
  const scaleNotes = getScaleNotes();
  const tempData = TEMPERAMENTS[S.temp];

  const chips = document.getElementById('scale-chips');
  chips.innerHTML = '';
  scaleNotes.forEach((n, i) => {
    const c = document.createElement('span');
    c.className = 'chip';
    c.textContent = CHROMATIC[n];
    if (i === 0) { c.style.cssText = 'background:rgba(245,158,11,0.15);color:#f59e0b;border-color:rgba(245,158,11,0.3)'; }
    else         { c.style.cssText = 'background:rgba(167,139,250,0.1);color:#a78bfa;border-color:rgba(167,139,250,0.22)'; }
    chips.appendChild(c);
  });

  const tbody = document.getElementById('info-body');
  tbody.innerHTML = '';
  scale.forEach((deg, i) => {
    const note = (deg + S.root) % 12;
    const row = document.createElement('tr');
    row.innerHTML = `
      <td style="color:${i===0?'#f59e0b':'#a78bfa'};font-weight:${i===0?'600':'400'}">${CHROMATIC[note]}</td>
      <td style="color:rgba(255,255,255,0.38)">${DEGREE_NAMES[deg]}</td>
      <td style="color:#60a5fa">${tempData.cents[deg].toFixed(1)}</td>
      <td style="color:#34d399;font-size:0.63rem;font-family:monospace">${tempData.ratios[deg]}</td>
    `;
    tbody.appendChild(row);
  });
}

// ═══════════════════════════════════════════════════════════════════
// RESIZE
// ═══════════════════════════════════════════════════════════════════

function resize() {
  const vp = vizPanel;
  const w = vp.clientWidth  || window.innerWidth;
  const stripH = isMobileSlides() ? 52 : 0;
  const h = vp.clientHeight || (window.innerHeight - 80 - stripH);
  const size = Math.max(60, Math.min(w - 40, h - 40, 640));
  canvas.width  = size;
  canvas.height = size;
  draw();
  if (S.fretboardOpen) drawFretboard();
  if (isMobileSlides()) { drawSequencer(); drawDrumMachine(); return; }
  if (document.getElementById('seq-wrap').classList.contains('open')) drawSequencer();
  if (document.getElementById('drum-wrap').classList.contains('open')) drawDrumMachine();
}

const ro = new ResizeObserver(() => resize());
ro.observe(vizPanel);

// ═══════════════════════════════════════════════════════════════════
// HEADER BUTTONS
// ═══════════════════════════════════════════════════════════════════

document.getElementById('btn-audio').addEventListener('click', function() {
  audio.enabled = !audio.enabled;
  this.classList.toggle('active-audio', audio.enabled);
  this.innerHTML = audio.enabled
    ? '<span class="hdr-icon">🎧</span><span class="btn-text"> Audio</span>'
    : '<span class="hdr-icon">🔇</span><span class="btn-text"> Muted</span>';
});

document.getElementById('btn-guitar').addEventListener('click', function() {
  S.fretboardOpen = !S.fretboardOpen;
  const wrap = document.getElementById('fretboard-wrap');
  wrap.classList.toggle('open', S.fretboardOpen);
  this.classList.toggle('active-fb', S.fretboardOpen);
  if (S.fretboardOpen) setTimeout(drawFretboard, 320);
});

document.getElementById('btn-synth').addEventListener('click', function() {
  const wrap = document.getElementById('synth-wrap');
  const open = wrap.classList.toggle('open');
  this.classList.toggle('active-synth', open);
});

document.getElementById('sel-scale').addEventListener('change', function() {
  S.scaleName = this.value;
  updateInfo(); draw(); drawFretboard();
});

['tog-cents','tog-labels'].forEach(id => {
  const btn = document.getElementById(id);
  const key = id === 'tog-cents' ? 'showCents' : 'showLabels';
  btn.addEventListener('click', () => {
    S[key] = !S[key];
    btn.classList.toggle('active', S[key]);
    draw();
  });
});

