requestAnimationFrame(() => requestAnimationFrame(resize));

// ═══════════════════════════════════════════════════════════════════
// MIDI ENGINE
// ═══════════════════════════════════════════════════════════════════

AudioEngine.prototype.stopAll = function() {
  if (!this.ready) return;
  // Slam kill to 0 — stays there until next _resume() restores it
  this.kill.gain.cancelScheduledValues(this.actx.currentTime);
  this.kill.gain.setValueAtTime(0, this.actx.currentTime);
};

class MidiParser {
  constructor(buffer) { this.data = new Uint8Array(buffer); this.pos = 0; }

  _u32() {
    const v = ((this.data[this.pos] << 24) | (this.data[this.pos+1] << 16) |
               (this.data[this.pos+2] << 8) | this.data[this.pos+3]) >>> 0;
    this.pos += 4; return v;
  }
  _u16() { const v = (this.data[this.pos] << 8) | this.data[this.pos+1]; this.pos += 2; return v; }
  _vlq() {
    let v = 0;
    for (let i = 0; i < 4; i++) {
      const b = this.data[this.pos++];
      v = (v << 7) | (b & 0x7f);
      if (!(b & 0x80)) break;
    }
    return v;
  }

  parse() {
    this.pos = 0;
    this._u32(); this._u32(); // MThd, length
    const format = this._u16();
    const numTracks = this._u16();
    const division = this._u16();
    const tracks = [];
    for (let t = 0; t < numTracks; t++) {
      this._u32(); // MTrk
      const len = this._u32();
      const end = this.pos + len;
      tracks.push(this._parseTrack(end));
      this.pos = end;
    }
    return { format, division, tracks };
  }

  _parseTrack(end) {
    const events = [];
    let tick = 0, rs = 0;
    while (this.pos < end) {
      tick += this._vlq();
      let st = this.data[this.pos];
      if (st & 0x80) { rs = st; this.pos++; } else { st = rs; }
      const type = st & 0xf0, ch = st & 0x0f;

      if (st === 0xff) {
        const mt = this.data[this.pos++], ml = this._vlq();
        if (mt === 0x51 && ml === 3) {
          const tempo = (this.data[this.pos] << 16) | (this.data[this.pos+1] << 8) | this.data[this.pos+2];
          events.push({ tick, type: 'tempo', tempo });
        }
        this.pos += ml;
      } else if (st === 0xf0 || st === 0xf7) {
        this.pos += this._vlq();
      } else if (type === 0x80 || type === 0x90) {
        const note = this.data[this.pos++], vel = this.data[this.pos++];
        events.push({ tick, type: (type === 0x90 && vel > 0) ? 'noteon' : 'noteoff', note, vel, ch });
      } else if (type === 0xa0 || type === 0xb0 || type === 0xe0) { this.pos += 2; }
        else if (type === 0xc0 || type === 0xd0) { this.pos += 1; }
        else { this.pos++; }
    }
    return events;
  }
}

function buildTimeline(parsed) {
  const { division, tracks } = parsed;
  const all = [];
  tracks.forEach(tr => tr.forEach(ev => all.push(ev)));
  all.sort((a, b) => a.tick - b.tick || (a.type === 'tempo' ? -1 : 1));

  // Build tempo map for accurate tick→seconds conversion
  const tempoMap = [{ tick: 0, tempo: 500000, sec: 0 }];
  all.forEach(ev => {
    if (ev.type !== 'tempo') return;
    const last = tempoMap[tempoMap.length - 1];
    const sec = last.sec + (ev.tick - last.tick) * last.tempo / 1e6 / division;
    tempoMap.push({ tick: ev.tick, tempo: ev.tempo, sec });
  });

  function t2s(tick) {
    let seg = tempoMap[0];
    for (const s of tempoMap) { if (s.tick <= tick) seg = s; else break; }
    return seg.sec + (tick - seg.tick) * seg.tempo / 1e6 / division;
  }

  const pending = {}, notes = [];
  all.forEach(ev => {
    if (ev.type !== 'noteon' && ev.type !== 'noteoff') return;
    const key = `${ev.ch}_${ev.note}`;
    if (ev.type === 'noteon') {
      if (!pending[key]) pending[key] = [];
      pending[key].push({ tick: ev.tick, vel: ev.vel });
    } else if (pending[key] && pending[key].length) {
      const on = pending[key].shift();
      const startS = t2s(on.tick), endS = t2s(ev.tick);
      notes.push({ startS, durationS: Math.max(endS - startS, 0.04), note: ev.note, vel: on.vel });
    }
  });
  // Close any unclosed note-ons
  Object.entries(pending).forEach(([key, arr]) => {
    arr.forEach(on => {
      const note = parseInt(key.split('_')[1]);
      notes.push({ startS: t2s(on.tick), durationS: 0.4, note, vel: on.vel });
    });
  });

  notes.sort((a, b) => a.startS - b.startS);
  return notes;
}


class MidiPlayer {
  constructor(timeline) {
    this.timeline = timeline;
    this.playing = false;
    this.startCtx = 0;
    this.speed = 1;
    this.totalS = timeline.length
      ? timeline[timeline.length-1].startS + timeline[timeline.length-1].durationS : 0;
    this._ivl = null;
    this._raf = null;
  }

  // Current scale as cents list (always reads live state)
  _scaleCents() {
    if (S.family === 'arabic' && MAQAM_CENTS[S.scaleName]) return MAQAM_CENTS[S.scaleName].slice();
    return getScale().map(d => d * 100);
  }

  // Nearest scale index by circular cent distance
  _nearestIdx(midiNote, scaleCents) {
    if (!scaleCents.length) return 0;
    const pcCents = ((midiNote - S.root) % 12 + 12) % 12 * 100;
    let best = 0, bd = Infinity;
    scaleCents.forEach((c, i) => {
      const d = Math.abs(((c - pcCents + 600) % 1200) - 600);
      if (d < bd) { bd = d; best = i; }
    });
    return best;
  }

  // Temperament-accurate frequency for a scale index, in the same octave as midiNote
  _freqFromIdx(idx, midiNote, scaleCents) {
    const midiHz = 440 * Math.pow(2, (midiNote - 69) / 12);
    let baseHz;
    if (S.family === 'arabic' && MAQAM_CENTS[S.scaleName]) {
      const rootHz = 261.62556 * Math.pow(2, S.root / 12);
      baseHz = rootHz * Math.pow(2, scaleCents[idx] / 1200);
    } else {
      baseHz = audio.degreeFreq(S.root, getScale()[idx], S.temp, 4);
    }
    return baseHz * Math.pow(2, Math.round(Math.log2(midiHz / baseHz)));
  }

  play(speed = 1) {
    audio._resume();
    this.speed = speed;
    this.playing = true;
    this.startCtx = audio.actx.currentTime + 0.05;
    this.timeline.forEach(n => { delete n._sched; delete n._qFreq; delete n._qMidi; });

    // Direction-rule context — resets automatically when scale/root/temp changes
    let prevIdx = -1, prevOrigMidi = null, prevSig = '';

    const LOOK = 0.25; // small look-ahead so scale changes take effect quickly

    this._ivl = setInterval(() => {
      if (!this.playing) return;
      const now = audio.actx.currentTime;
      const elapsed = (now - this.startCtx) * speed;
      const scaleCents = this._scaleCents();
      const sig = `${S.root}|${S.temp}|${S.family}|${S.scaleName}`;

      // Scale/root/temp changed → reset direction context so next notes start fresh
      if (sig !== prevSig) { prevIdx = -1; prevOrigMidi = null; prevSig = sig; }

      for (const note of this.timeline) {
        if (note._sched) continue;
        const t = note.startS / speed;
        if (t > elapsed + LOOK) break; // timeline is sorted

        // Quantize to nearest scale degree
        let idx = this._nearestIdx(note.note, scaleCents);

        // Direction rule: if same scale degree as last but MIDI moved, step in that direction
        if (prevIdx >= 0 && idx === prevIdx && note.note !== prevOrigMidi) {
          const dir = note.note > prevOrigMidi ? +1 : -1;
          const ni = prevIdx + dir;
          if (ni >= 0 && ni < scaleCents.length) idx = ni;
        }

        const freq = this._freqFromIdx(idx, note.note, scaleCents);
        note._qFreq = freq;
        note._qMidi = Math.round(69 + 12 * Math.log2(freq / 440));
        prevIdx = idx;
        prevOrigMidi = note.note;

        audio._playHz(freq, Math.max(this.startCtx + t - now, 0),
          Math.min(note.durationS / speed, 1.4), (note.vel / 127) * 0.55);
        note._sched = true;
      }

      if (elapsed > this.totalS + 0.8) this.stop();
    }, 50); // 50ms interval to keep up with 250ms look-ahead

    const rafLoop = () => {
      if (!this.playing) return;
      const elapsed = (audio.actx.currentTime - this.startCtx) * speed;
      document.getElementById('midi-prog').style.width =
        Math.min(elapsed / this.totalS * 100, 100) + '%';
      let active = null;
      for (const n of this.timeline) {
        const t = n.startS / speed;
        if (elapsed >= t - 0.02 && elapsed < t + n.durationS / speed) { active = n; break; }
      }
      midiActiveQuantizedMidi = active ? active._qMidi : null;
      draw();
      if (S.fretboardOpen) drawFretboard();
      this._raf = requestAnimationFrame(rafLoop);
    };
    this._raf = requestAnimationFrame(rafLoop);
  }

  stop() {
    this.playing = false;
    clearInterval(this._ivl);
    if (this._raf) cancelAnimationFrame(this._raf);
    audio.stopAll();
    midiActiveQuantizedMidi = null;
    document.getElementById('midi-prog').style.width = '0%';
    document.getElementById('btn-midi-play').style.display = '';
    document.getElementById('btn-midi-stop').style.display = 'none';
    draw();
    if (S.fretboardOpen) drawFretboard();
  }

  // Change speed mid-playback: rebase startCtx and flush look-ahead buffer
  setSpeed(newSpeed) {
    if (!this.playing) return;
    const now = audio.actx.currentTime;
    const elapsedTL = (now - this.startCtx) * this.speed;
    this.speed = newSpeed;
    this.startCtx = now - elapsedTL / newSpeed;
    // Un-schedule notes still in the look-ahead window so they're rescheduled at new speed
    this.timeline.forEach(n => { if (n._sched && n.startS > elapsedTL) delete n._sched; });
    // Kill audio buffer then immediately restore so scheduler fills fresh
    audio.stopAll();
    audio._resume();
  }
}

// ═══════════════════════════════════════════════════════════════════
// SEQUENCER ENGINE
// ═══════════════════════════════════════════════════════════════════

const seqCanvas = document.getElementById('seq-canvas');
const seqCtx = seqCanvas.getContext('2d');

// Defined properly later once DOM is ready; hoisted stub avoids ReferenceError
let syncPlayUI = (playing) => {
  const play = document.getElementById('btn-seq-play');
  const stop = document.getElementById('btn-seq-stop');
  if (play) play.style.display = playing ? 'none' : '';
  if (stop) stop.style.display = playing ? '' : 'none';
};

const seqEngine = {
  playing: false,
  step: 0,
  nextTime: 0,
  startTime: 0,
  displayStep: -1,
  drumDisplayStep: -1,
  _ivl: null,
  _raf: null,

  _playStep(step, time) {
    const scale = getScale();
    const n = scale.length;
    if (n === 0) return;
    const rootHz = 261.62556 * Math.pow(2, S.root / 12);
    const noteDur = Math.max(seqStepDur() * SEQ.gate, 0.04);

    for (let si = 0; si < n; si++) {
      if (!SEQ.grid[`${si}_${step}`]) continue;
      let freq;
      if (S.family === 'arabic' && MAQAM_CENTS[S.scaleName]) {
        const cents = MAQAM_CENTS[S.scaleName][si] ?? 0;
        freq = rootHz * Math.pow(2, cents / 1200);
      } else {
        freq = audio.degreeFreq(S.root, scale[si], S.temp, 4);
      }
      audio._playHz(freq, Math.max(time - audio.actx.currentTime, 0), noteDur, 0.72);
    }
  },

  _tick() {
    const LOOK    = 0.15;
    const dur     = seqStepDur();
    const melLoop = Math.max(1, Math.min(SEQ.loopLen,  seqSteps()));
    const drmLoop = Math.max(1, Math.min(drumLoopLen,  seqSteps()));
    const loopLen = Math.max(melLoop, drmLoop); // master counter covers both
    const melDur  = melLoop * dur;
    const drmDur  = drmLoop * dur;
    const now     = audio.actx.currentTime;

    // ── Audio scheduling ────────────────────────────────────────────
    // _barJoining: suppress audio until next bar boundary after phase-lock join
    if (this._barJoining && this.nextTime <= now + LOOK) {
      this._barJoining = false;
    }
    if (!this._barJoining) {
      while (this.nextTime < now + LOOK) {
        this._playStep(this.step % melLoop, this.nextTime);
        drumPlayStep(this.step % drmLoop,   this.nextTime); // drum hits pre-scheduled here
        this.nextTime += dur;
        this.step = (this.step + 1) % loopLen;
      }
    }

    // ── Display steps ────────────────────────────────────────────────
    if (epochMs !== null) {
      // World clock: both instances show the same step at the same moment
      const worldElapsed   = (sharedNow() - epochMs) / 1000;
      this.displayStep     = worldElapsed < 0 ? 0 : Math.floor((worldElapsed % melDur) / dur) % melLoop;
      this.drumDisplayStep = worldElapsed < 0 ? 0 : Math.floor((worldElapsed % drmDur) / dur) % drmLoop;

      // ── Periodic audio correction (~every 1 s) ────────────────────
      if (!this._barJoining) {
        if (this._corrTick === undefined) this._corrTick = 0;
        if (++this._corrTick % 50 === 0) {
          this.startTime = now - worldElapsed;
          const phaseInStep    = worldElapsed % dur;
          const targetNextTime = now + (dur - phaseInStep);
          const drift          = targetNextTime - this.nextTime;
          if (Math.abs(drift) > 0.001 && Math.abs(drift) < dur * 0.5) {
            this.nextTime += drift;
            this.step = (Math.floor((worldElapsed % melDur) / dur) + 1) % loopLen;
          }
        }
      }
    } else {
      // Standalone fallback — local audio clock only
      const elapsed        = now - this.startTime;
      this.displayStep     = elapsed < 0 ? 0 : Math.floor((elapsed % melDur) / dur) % melLoop;
      this.drumDisplayStep = elapsed < 0 ? 0 : Math.floor((elapsed % drmDur) / dur) % drmLoop;
    }
  },

  play(remoteEpochMs = null) {
    if (activeMidiPlayer) { activeMidiPlayer.stop(); activeMidiPlayer = null; }
    audio._resume();
    this.playing = true;

    if (remoteEpochMs !== null) {
      // ── Follower: sync to the remote epoch ────────────────────────
      epochMs = remoteEpochMs;
      const dur      = seqStepDur();
      const loopLen  = Math.max(1, Math.min(SEQ.loopLen, seqSteps()));
      const loopDur  = loopLen * dur;
      const worldElapsed = Math.max(0, (sharedNow() - epochMs) / 1000);
      const posInLoop    = worldElapsed % loopDur;
      this.displayStep   = Math.floor(posInLoop / dur) % loopLen;
      this.startTime     = audio.actx.currentTime - worldElapsed;
      // nextTime = audio time of the next unscheduled step boundary
      const timeToNext   = dur - (posInLoop % dur);
      this.nextTime      = audio.actx.currentTime + timeToNext;
      this.step          = (this.displayStep + 1) % loopLen;
    } else if (peerEpochMs !== null) {
      // ── Bar-quantized join: wait for next bar boundary so step 0 fires
      // on both instances at the exact same world-clock moment.
      epochMs = peerEpochMs;
      const dur          = seqStepDur();
      const loopLen      = Math.max(1, Math.min(SEQ.loopLen, seqSteps()));
      const loopDur      = loopLen * dur;
      const worldElapsed = Math.max(0, (sharedNow() - epochMs) / 1000);
      const posInLoop    = worldElapsed % loopDur;
      const timeToBar    = loopDur - posInLoop;   // seconds until next bar start

      // displayStep follows world clock immediately (visual feedback)
      this.displayStep   = Math.floor(posInLoop / dur) % loopLen;
      this.startTime     = audio.actx.currentTime + timeToBar; // step 0 at bar start
      this.nextTime      = audio.actx.currentTime + timeToBar; // first audio event
      this.step          = 0;
      this._barJoining   = true;   // suppress audio until bar arrives
      this._corrTick     = 0;
      syncSend({ type: 'JOINED', epochMs, masterBpm, ...syncGetFullState() });
    } else {
      // ── Leader: no peer playing — create a fresh epoch ────────────
      epochMs            = sharedNow();
      masterBpm          = SEQ.bpm;
      this.step          = 0;
      this.displayStep   = 0;
      this.startTime     = audio.actx.currentTime;
      this.nextTime      = this.startTime + 0.02;
      syncSend({ type: 'PLAY', epochMs, masterBpm, ...syncGetFullState() });
    }

    this._ivl = setInterval(() => { if (this.playing) this._tick(); }, 20);
    const raf = () => { if (!this.playing) return; drawSequencer(); drawDrumMachine(); draw(); this._raf = requestAnimationFrame(raf); };
    this._raf = requestAnimationFrame(raf);
    syncPlayUI(true);
  },

  stop(fromRemote = false) {
    this.playing      = false;
    this._barJoining  = false;
    this._corrTick    = 0;
    clearInterval(this._ivl);
    if (this._raf) cancelAnimationFrame(this._raf);
    this.displayStep = -1;
    this.drumDisplayStep = -1;
    epochMs = null;
    if (!fromRemote) syncSend({ type: 'STOP' });
    syncPlayUI(false);
    drawSequencer();
    drawDrumMachine();
  },

  rebase(fromRemote = false) { // call when bpm/rhythm changes mid-play
    if (!this.playing) return;
    const now = audio.actx.currentTime;
    const loopLen = Math.max(1, Math.min(SEQ.loopLen, seqSteps()));
    this.startTime = now - this.displayStep * seqStepDur();
    this.nextTime  = now + 0.02;
    this.step = (this.displayStep + 1) % loopLen;
    // Shift the epoch so the current step maps correctly at the new tempo
    if (epochMs !== null) {
      epochMs = sharedNow() - this.displayStep * seqStepDur() * 1000;
      if (!fromRemote) {
        masterBpm = Math.round(SEQ.bpm / syncTempoRatio);
        syncSend({ type: 'REBASE', epochMs, masterBpm, rhythmKey: SEQ.rhythmKey, loopLen: SEQ.loopLen });
      }
    }
  },
};

// Returns frequencies (Hz) of notes active at the current sequencer display step
function getSeqActiveFreqs() {
  if (!seqEngine.playing || seqEngine.displayStep < 0) return [];
  const step = seqEngine.displayStep;
  const scale = getScale();
  const n = scale.length;
  const rootHz = 261.62556 * Math.pow(2, S.root / 12);
  const freqs = [];
  for (let si = 0; si < n; si++) {
    if (!SEQ.grid[`${si}_${step}`]) continue;
    if (S.family === 'arabic' && MAQAM_CENTS[S.scaleName]) {
      freqs.push(rootHz * Math.pow(2, (MAQAM_CENTS[S.scaleName][si] ?? 0) / 1200));
    } else {
      freqs.push(audio.degreeFreq(S.root, scale[si], S.temp, 4));
    }
  }
  return freqs;
}

let _seqFbLastStep = -1;

function drawSequencer() {
  const wrap = seqCanvas.parentElement;
  const DPR = window.devicePixelRatio || 1;
  const W = wrap.clientWidth, H = wrap.clientHeight;
  if (W === 0 || H === 0) return;
  seqCanvas.width  = W * DPR; seqCanvas.height = H * DPR;
  seqCanvas.style.width = W + 'px'; seqCanvas.style.height = H + 'px';
  seqCtx.scale(DPR, DPR);

  const scale = getScale();
  const n = scale.length;
  const steps = seqSteps();
  const spb = seqR().spb;
  const LM = 30; // left label margin
  const gW = (W - LM) / steps;
  const gH = H / Math.max(n, 1);

  seqCtx.fillStyle = '#070512';
  seqCtx.fillRect(0, 0, W, H);
  seqCtx.fillStyle = 'rgba(255,255,255,0.022)';
  seqCtx.fillRect(0, 0, LM, H);

  if (n === 0) return;

  for (let row = 0; row < n; row++) {
    const si = n - 1 - row; // row 0 = top = highest pitch
    const y  = row * gH;
    const noteIdx = (scale[si] + S.root) % 12;
    const isRoot  = si === 0;

    // Root row tint
    if (isRoot) { seqCtx.fillStyle = 'rgba(245,158,11,0.05)'; seqCtx.fillRect(LM, y, W - LM, gH); }

    // Note label
    const fs = Math.max(Math.min(Math.floor(gH * 0.52), 11), 7);
    seqCtx.font = `bold ${fs}px system-ui`;
    seqCtx.textAlign = 'center'; seqCtx.textBaseline = 'middle';
    seqCtx.fillStyle = isRoot ? '#f59e0b' : 'rgba(167,139,250,0.7)';
    seqCtx.fillText(CHROMATIC[noteIdx], LM / 2, y + gH / 2);

    for (let st = 0; st < steps; st++) {
      const x       = LM + st * gW;
      const active   = !!SEQ.grid[`${si}_${st}`];
      const isCur    = st === seqEngine.displayStep && seqEngine.playing;
      const isBeat   = Number.isInteger(st / spb) || Math.abs(st % spb) < 0.001;
      const isBar    = Math.abs(st % (spb * 4)) < 0.001;

      let fill;
      if      (active && isCur) fill = 'rgba(245,158,11,0.92)';
      else if (active)          fill = 'rgba(167,139,250,0.80)';
      else if (isCur)           fill = 'rgba(255,255,255,0.16)';
      else if (isBar)           fill = 'rgba(255,255,255,0.065)';
      else if (isBeat)          fill = 'rgba(255,255,255,0.038)';
      else                      fill = 'rgba(255,255,255,0.016)';

      seqCtx.fillStyle = fill;
      seqCtx.fillRect(x + 0.5, y + 0.5, gW - 1, gH - 1);
    }
  }

  // Vertical grid lines
  for (let st = 0; st <= steps; st++) {
    const x = LM + st * gW;
    const isBar   = Math.abs(st % (spb * 4)) < 0.001;
    const isBeat  = Number.isInteger(st / spb) || Math.abs(st % spb) < 0.001;
    seqCtx.beginPath(); seqCtx.moveTo(x, 0); seqCtx.lineTo(x, H);
    seqCtx.strokeStyle = isBar ? 'rgba(255,255,255,0.24)' : isBeat ? 'rgba(255,255,255,0.1)' : 'rgba(255,255,255,0.04)';
    seqCtx.lineWidth = 1; seqCtx.stroke();
  }
  // Horizontal grid lines
  for (let row = 0; row <= n; row++) {
    const y = row * gH;
    seqCtx.beginPath(); seqCtx.moveTo(LM, y); seqCtx.lineTo(W, y);
    seqCtx.strokeStyle = 'rgba(255,255,255,0.07)'; seqCtx.lineWidth = 1; seqCtx.stroke();
  }
  // Label separator
  seqCtx.beginPath(); seqCtx.moveTo(LM, 0); seqCtx.lineTo(LM, H);
  seqCtx.strokeStyle = 'rgba(255,255,255,0.14)'; seqCtx.lineWidth = 1; seqCtx.stroke();

  // Loop length overlay — dim steps outside active loop
  const loopLen = Math.max(1, Math.min(SEQ.loopLen, steps));
  if (loopLen < steps) {
    const loopEndX = LM + loopLen * gW;
    seqCtx.fillStyle = 'rgba(0,0,0,0.45)';
    seqCtx.fillRect(loopEndX, 0, W - loopEndX, H);
    // Loop end marker line
    seqCtx.beginPath(); seqCtx.moveTo(loopEndX, 0); seqCtx.lineTo(loopEndX, H);
    seqCtx.strokeStyle = 'rgba(167,139,250,0.6)'; seqCtx.lineWidth = 2; seqCtx.stroke();
    // Loop bracket
    seqCtx.fillStyle = 'rgba(167,139,250,0.55)';
    seqCtx.fillRect(LM, 0, loopLen * gW, 2);
  }

  // Trigger fretboard redraw when playhead step changes
  if (seqEngine.playing && S.fretboardOpen && seqEngine.displayStep !== _seqFbLastStep) {
    _seqFbLastStep = seqEngine.displayStep;
    drawFretboard();
  }
  if (!seqEngine.playing && _seqFbLastStep !== -1) {
    _seqFbLastStep = -1;
    if (S.fretboardOpen) drawFretboard();
  }
}

seqCanvas.addEventListener('click', e => {
  const rect = seqCanvas.getBoundingClientRect();
  const px = e.clientX - rect.left, py = e.clientY - rect.top;
  const W = seqCanvas.clientWidth,  H  = seqCanvas.clientHeight;
  const scale = getScale(), n = scale.length;
  if (n === 0 || px < 30) return;
  const gW = (W - 30) / seqSteps(), gH = H / n;
  const st = Math.floor((px - 30) / gW), row = Math.floor(py / gH);
  const si = n - 1 - row;
  if (st < 0 || st >= seqSteps() || si < 0 || si >= n) return;
  const key = `${si}_${st}`;
  if (SEQ.grid[key]) { delete SEQ.grid[key]; syncSend({ type: 'GRID_SET', key, val: false }); }
  else               { SEQ.grid[key] = true;  syncSend({ type: 'GRID_SET', key, val: true  }); }
  drawSequencer();
});

function seqLoadDemo() {
  SEQ.grid = {};
  const n = getScale().length;
  if (n === 0) return;
  // Flowing arpeggio-melody: works on any scale size
  // [scaleIdx 0=root, stepIndex] — clamps to available rows
  const pat = [
    [0,0],[2,1],[4,2],[2,3],  [3,4],[2,5],[1,6],[0,7],
    [0,8],[4,9],[6,10],[4,11],[5,12],[3,13],[1,14],[0,15],
  ];
  const steps = seqSteps();
  pat.forEach(([si, st]) => {
    if (st < steps) SEQ.grid[`${Math.min(si, n - 1)}_${st}`] = true;
  });
  drawSequencer();
}

