// Helper: initialize audio engine lazily, then apply
function withAudio(fn) {
  audio._resume();
  // Wait one microtask for _init to complete
  setTimeout(fn, 0);
}

document.getElementById('mix-melody').addEventListener('input', function() {
  const v = parseInt(this.value) / 100;
  document.getElementById('mix-mel-val').textContent = parseInt(this.value) + '%';
  withAudio(() => { if (audio.melodyBus) audio.melodyBus.gain.value = v; });
});

document.getElementById('mix-master').addEventListener('input', function() {
  const v = parseInt(this.value) / 100;
  document.getElementById('mix-master-val').textContent = parseInt(this.value) + '%';
  withAudio(() => { if (audio.master) audio.master.gain.setTargetAtTime(v, audio.actx.currentTime, 0.02); });
});

document.getElementById('mix-drums').addEventListener('input', function() {
  const v = parseInt(this.value) / 100;
  document.getElementById('mix-drm-val').textContent = parseInt(this.value) + '%';
  withAudio(() => { if (audio.drumBus) audio.drumBus.gain.value = v; });
});

document.getElementById('mix-reverb').addEventListener('input', function() {
  const v = parseInt(this.value);
  document.getElementById('mix-rev-val').textContent = v + '%';
  withAudio(() => { if (audio.revSend) audio.revSend.gain.setTargetAtTime(v / 100 * 0.8, audio.actx.currentTime, 0.02); });
});

document.getElementById('mix-dist').addEventListener('input', function() {
  const v = parseInt(this.value);
  document.getElementById('mix-dist-val').textContent = v + '%';
  withAudio(() => {
    if (!audio.distNode) return;
    audio.applyDistortion(v / 100);
    audio.distWet.gain.setTargetAtTime(v / 100 * 0.7, audio.actx.currentTime, 0.02);
  });
});

document.getElementById('mix-delay-wet').addEventListener('input', function() {
  const v = parseInt(this.value);
  document.getElementById('mix-dly-val').textContent = v + '%';
  withAudio(() => { if (audio.delayWet) audio.delayWet.gain.setTargetAtTime(v / 100 * 0.8, audio.actx.currentTime, 0.02); });
});

document.getElementById('mix-delay-time').addEventListener('input', function() {
  const v = parseInt(this.value);
  document.getElementById('mix-dlt-val').textContent = v + 'ms';
  withAudio(() => { if (audio.delayNode) audio.delayNode.delayTime.setTargetAtTime(v / 1000, audio.actx.currentTime, 0.02); });
});

document.getElementById('mix-delay-fb').addEventListener('input', function() {
  const v = parseInt(this.value);
  document.getElementById('mix-dfb-val').textContent = v + '%';
  withAudio(() => { if (audio.delayFeedback) audio.delayFeedback.gain.setTargetAtTime(v / 100, audio.actx.currentTime, 0.02); });
});

// ── GLOBAL FILTER (Mixer) ────────────────────────────────────────────
document.getElementById('mix-gflt-cut').addEventListener('input', function() {
  const v = parseFloat(this.value);
  const hz = v >= 100 ? 20000 : Math.round(20 * Math.pow(1000, v / 100));
  const label = v >= 100 ? 'Open' : (hz >= 1000 ? (hz / 1000).toFixed(1) + 'kHz' : hz + 'Hz');
  document.getElementById('mix-gflt-val').textContent = label;
  withAudio(() => { if (audio.globalFilter) audio.globalFilter.frequency.setTargetAtTime(hz, audio.actx.currentTime, 0.015); });
});

document.getElementById('mix-gflt-res').addEventListener('input', function() {
  const v = parseFloat(this.value);
  document.getElementById('mix-gflt-res-val').textContent = v.toFixed(1);
  withAudio(() => { if (audio.globalFilter) audio.globalFilter.Q.setTargetAtTime(v, audio.actx.currentTime, 0.015); });
});

document.querySelectorAll('[data-type]').forEach(btn => {
  btn.addEventListener('click', function() {
    document.querySelectorAll('[data-type]').forEach(b => b.classList.remove('active'));
    this.classList.add('active');
    withAudio(() => { if (audio.globalFilter) audio.globalFilter.type = this.dataset.type; });
  });
});

// ── MIXER VISUAL CONTROLS ─────────────────────────────────────────────
(function initMixerVisuals() {
  const COL4 = '#60a5fa';
  const COL2 = '#34d399';
  const COLF = '#fb923c';
  const COLR = '#f87171';

  function valLabelMix(ctx, text, w, h, color) {
    ctx.fillStyle = color || 'rgba(148,163,184,0.82)';
    ctx.font = `bold ${Math.round(h * 0.24)}px monospace`;
    ctx.textAlign = 'center'; ctx.textBaseline = 'bottom';
    ctx.fillText(text, w / 2, h - 2);
  }

  function drawFader(ctx, w, h, t, color, unityT) {
    const cx = w / 2, trackW = 4;
    const trackTop = h * 0.05, trackBot = h * 0.88;
    const trackH = trackBot - trackTop;
    const thumbY = trackBot - t * trackH;
    const thumbW = Math.floor(w * 0.70), thumbH = 11;
    const zeroY = trackBot - (unityT ?? (100 / 150)) * trackH;
    ctx.fillStyle = 'rgba(255,255,255,0.07)';
    ctx.fillRect(cx - trackW / 2, trackTop, trackW, trackH);
    if (trackBot - thumbY > 1) {
      ctx.fillStyle = color + '3a';
      ctx.fillRect(cx - trackW / 2, thumbY, trackW, trackBot - thumbY);
    }
    ctx.beginPath(); ctx.moveTo(cx - thumbW / 2 - 3, zeroY); ctx.lineTo(cx + thumbW / 2 + 3, zeroY);
    ctx.strokeStyle = 'rgba(255,255,255,0.22)'; ctx.lineWidth = 1; ctx.stroke();
    ctx.fillStyle = color;
    ctx.fillRect(cx - thumbW / 2, thumbY - thumbH / 2, thumbW, thumbH);
    ctx.fillStyle = 'rgba(255,255,255,0.22)';
    ctx.fillRect(cx - thumbW / 2 + 3, thumbY - thumbH / 2 + 2, thumbW - 6, 2);
    ctx.beginPath(); ctx.moveTo(cx - thumbW / 2 + 4, thumbY); ctx.lineTo(cx + thumbW / 2 - 4, thumbY);
    ctx.strokeStyle = 'rgba(255,255,255,0.38)'; ctx.lineWidth = 1; ctx.stroke();
  }

  function drawMixReverb(ctx, w, h, t) {
    const n = Math.max(4, Math.round(4 + t * 14));
    for (let i = 0; i < n; i++) {
      const x = (i / n) * w, bw = (w / n) * 0.55;
      const decay = Math.exp(-i * 2.2 / n);
      const bh = h * 0.76 * decay;
      ctx.fillStyle = `rgba(96,165,250,${(0.1 + decay * 0.6).toFixed(2)})`;
      ctx.fillRect(x + bw * 0.1, (h - bh) / 2, bw, bh);
    }
  }

  function drawMixDrive(ctx, w, h, t) {
    const mid = h * 0.5, amp = h * 0.38, clip = Math.max(0.04, 1 - t * 0.94);
    ctx.beginPath();
    for (let x = 0; x <= w; x++) {
      const s = Math.max(-clip, Math.min(clip, Math.sin((x / w) * 2.5 * Math.PI * 2))) / clip;
      x === 0 ? ctx.moveTo(x, mid - s * amp) : ctx.lineTo(x, mid - s * amp);
    }
    ctx.strokeStyle = t > 0.05 ? COLR : 'rgba(248,113,113,0.28)'; ctx.lineWidth = 2; ctx.stroke();
  }

  function drawMixDelayWet(ctx, w, h, t) {
    const mid = h * 0.5, amp = h * 0.38, echoes = Math.round(t * 3);
    for (let e = 0; e <= echoes; e++) {
      const x = (e / (echoes + 1.5)) * w * 0.9;
      const a = e === 0 ? 0.8 : Math.pow(t, e * 0.7) * 0.72;
      ctx.fillStyle = `rgba(96,165,250,${(a * 0.65).toFixed(2)})`;
      ctx.fillRect(x + 2, mid - a * amp, w / (echoes + 2.5) * 0.5, a * amp * 2);
    }
  }

  function drawMixDelayTime(ctx, w, h, t) {
    const mid = h * 0.5, mx = w * 0.07 + t * w * 0.85;
    ctx.beginPath(); ctx.moveTo(4, mid); ctx.lineTo(w - 4, mid);
    ctx.strokeStyle = 'rgba(96,165,250,0.12)'; ctx.lineWidth = 1; ctx.stroke();
    ctx.fillStyle = 'rgba(96,165,250,0.75)'; ctx.fillRect(4, mid - h * 0.3, 3, h * 0.6);
    ctx.fillStyle = 'rgba(96,165,250,0.38)'; ctx.fillRect(mx, mid - h * 0.22, 3, h * 0.44);
    ctx.beginPath(); ctx.moveTo(7, mid); ctx.lineTo(mx, mid);
    ctx.strokeStyle = 'rgba(96,165,250,0.22)'; ctx.lineWidth = 1;
    ctx.setLineDash([3, 3]); ctx.stroke(); ctx.setLineDash([]);
  }

  function drawMixDelayFB(ctx, w, h, t) {
    const mid = h * 0.5, reps = Math.max(2, Math.round(2 + t * 7));
    for (let i = 0; i < reps; i++) {
      const x = (i / reps) * w;
      const a = Math.min(0.84, Math.pow(t + 0.08, i * 0.55) * 0.82);
      const bh = Math.max(2, a * h * 0.72);
      ctx.fillStyle = `rgba(96,165,250,${a.toFixed(2)})`;
      ctx.fillRect(x + 1, mid - bh / 2, (w / reps) * 0.48, bh);
    }
  }

  function drawMixFilterCut(ctx, w, h, t) {
    const cutX = w * 0.06 + t * w * 0.82, topY = h * 0.14, botY = h * 0.82;
    ctx.beginPath(); ctx.moveTo(0, topY); ctx.lineTo(cutX, topY);
    ctx.bezierCurveTo(cutX + w * 0.09, topY, cutX + w * 0.09, botY, cutX + w * 0.2, botY);
    ctx.lineTo(w, botY); ctx.strokeStyle = COLF; ctx.lineWidth = 2; ctx.stroke();
    ctx.beginPath(); ctx.moveTo(cutX, topY - 3); ctx.lineTo(cutX, botY + 3);
    ctx.strokeStyle = 'rgba(251,146,60,0.25)'; ctx.lineWidth = 1;
    ctx.setLineDash([3, 3]); ctx.stroke(); ctx.setLineDash([]);
  }

  function drawMixFilterReso(ctx, w, h, t) {
    const baseY = h * 0.76, cx = w * 0.5, ph = t * h * 0.6;
    const spread = Math.max(10, w * 0.28 * (1 - t * 0.75));
    ctx.beginPath(); ctx.moveTo(0, baseY); ctx.lineTo(w, baseY);
    ctx.strokeStyle = 'rgba(251,146,60,0.22)'; ctx.lineWidth = 1; ctx.stroke();
    if (ph > 1) {
      ctx.beginPath(); ctx.moveTo(0, baseY);
      ctx.bezierCurveTo(cx - spread, baseY, cx - spread / 3, baseY - ph, cx, baseY - ph);
      ctx.bezierCurveTo(cx + spread / 3, baseY - ph, cx + spread, baseY, w, baseY);
      ctx.strokeStyle = COLF; ctx.lineWidth = 2; ctx.stroke();
    }
  }

  const allMixCvs = [];

  function paintMix(cvs, slider, fn) {
    if (!cvs.width || !cvs.height) return;
    const ctx = cvs.getContext('2d');
    ctx.clearRect(0, 0, cvs.width, cvs.height);
    const v = parseFloat(slider.value);
    const t = (v - parseFloat(slider.min)) / (parseFloat(slider.max) - parseFloat(slider.min));
    fn(ctx, cvs.width, cvs.height, t, v);
  }

  function redrawMix() {
    allMixCvs.forEach(({ cvs, slider, fn }) => {
      const rect = cvs.getBoundingClientRect();
      if (rect.width  > 0) cvs.width  = Math.round(rect.width);
      if (rect.height > 0) cvs.height = Math.round(rect.height);
      paintMix(cvs, slider, fn);
    });
  }

  // Vertical fader canvases (Melody, Drums, Master)
  [
    { cvs: document.getElementById('mix-fader-melody'), slider: document.getElementById('mix-melody'), color: COL4, unityT: 100/150 },
    { cvs: document.getElementById('mix-fader-drums'),  slider: document.getElementById('mix-drums'),  color: COL2, unityT: 100/150 },
    { cvs: document.getElementById('mix-fader-master'), slider: document.getElementById('mix-master'), color: '#a78bfa', unityT: 1.0 },
  ].forEach(({ cvs, slider, color, unityT }) => {
    if (!cvs || !slider) return;
    const fn = (ctx, w, h, t) => drawFader(ctx, w, h, t, color, unityT);
    allMixCvs.push({ cvs, slider, fn });
    function repaint() { paintMix(cvs, slider, fn); }
    slider.addEventListener('input', repaint);
    let startY, startVal, dragging = false;
    function onStart(y) { startY = y; startVal = parseFloat(slider.value); }
    function onMove(y) {
      const dy = startY - y;
      const range = parseFloat(slider.max) - parseFloat(slider.min);
      const step = parseFloat(slider.step) || 1;
      const nv = Math.max(parseFloat(slider.min), Math.min(parseFloat(slider.max),
        Math.round((startVal + (dy / cvs.height) * range) / step) * step));
      slider.value = nv;
      slider.dispatchEvent(new Event('input', { bubbles: true }));
      repaint();
    }
    cvs.addEventListener('touchstart', e => { onStart(e.touches[0].clientY); e.preventDefault(); }, { passive: false });
    cvs.addEventListener('touchmove',  e => { onMove(e.touches[0].clientY);  e.preventDefault(); }, { passive: false });
    cvs.addEventListener('mousedown',  e => { dragging = true; onStart(e.clientY); e.preventDefault(); });
    window.addEventListener('mousemove', e => { if (dragging) onMove(e.clientY); });
    window.addEventListener('mouseup',   () => { dragging = false; });
  });

  // Effect vis-ctrl canvases
  const MIX_DRAW = {
    'mix-reverb':     (ctx, w, h, t, v) => { drawMixReverb(ctx, w, h, t);    valLabelMix(ctx, v + '%', w, h); },
    'mix-dist':       (ctx, w, h, t, v) => { drawMixDrive(ctx, w, h, t);     valLabelMix(ctx, v + '%', w, h, COLR); },
    'mix-delay-wet':  (ctx, w, h, t, v) => { drawMixDelayWet(ctx, w, h, t);  valLabelMix(ctx, v + '%', w, h); },
    'mix-delay-time': (ctx, w, h, t, v) => { drawMixDelayTime(ctx, w, h, t); valLabelMix(ctx, v + 'ms', w, h); },
    'mix-delay-fb':   (ctx, w, h, t, v) => { drawMixDelayFB(ctx, w, h, t);   valLabelMix(ctx, v + '%', w, h); },
    'mix-gflt-cut':   (ctx, w, h, t, v) => { drawMixFilterCut(ctx, w, h, t); valLabelMix(ctx, v >= 100 ? 'Open' : Math.round(20 * Math.pow(1000, v / 100)) + 'Hz', w, h, COLF); },
    'mix-gflt-res':   (ctx, w, h, t, v) => { drawMixFilterReso(ctx, w, h, t); valLabelMix(ctx, parseFloat(v).toFixed(1), w, h, COLF); },
  };

  Object.keys(MIX_DRAW).forEach(id => {
    const slider = document.getElementById(id);
    if (!slider) return;
    const fn = MIX_DRAW[id];
    const cvs = document.createElement('canvas');
    cvs.className = 'vis-ctrl mix-vis-ctrl';
    cvs.height = 50;
    slider.parentNode.insertBefore(cvs, slider);
    allMixCvs.push({ cvs, slider, fn });
    function repaint() { paintMix(cvs, slider, fn); }
    slider.addEventListener('input', repaint);
    let startX, startVal, dragging = false;
    function onStart(x) { startX = x; startVal = parseFloat(slider.value); }
    function onMove(x) {
      const dx = x - startX;
      const range = parseFloat(slider.max) - parseFloat(slider.min);
      const step = parseFloat(slider.step) || 1;
      const nv = Math.max(parseFloat(slider.min), Math.min(parseFloat(slider.max),
        Math.round((startVal + (dx / cvs.width) * range) / step) * step));
      slider.value = nv;
      slider.dispatchEvent(new Event('input', { bubbles: true }));
      repaint();
    }
    cvs.addEventListener('touchstart', e => { onStart(e.touches[0].clientX); e.preventDefault(); }, { passive: false });
    cvs.addEventListener('touchmove',  e => { onMove(e.touches[0].clientX);  e.preventDefault(); }, { passive: false });
    cvs.addEventListener('mousedown',  e => { dragging = true; onStart(e.clientX); e.preventDefault(); });
    window.addEventListener('mousemove', e => { if (dragging) onMove(e.clientX); });
    window.addEventListener('mouseup',   () => { dragging = false; });
  });

  // Trigger redraw when mixer opens
  document.getElementById('mixer-wrap')?.addEventListener('transitionend', () => {
    if (document.getElementById('mixer-wrap').classList.contains('open'))
      requestAnimationFrame(redrawMix);
  });
  document.getElementById('btn-mixer')?.addEventListener('click', () => {
    requestAnimationFrame(() => requestAnimationFrame(redrawMix));
  });
})();

// ── PLAY UI SYNC (overwrites hoisted stub with full version) ─────────
syncPlayUI = (playing) => {
  ['btn-seq-play', 'mob-btn-play'].forEach(id => {
    const el = document.getElementById(id); if (el) el.style.display = playing ? 'none' : '';
  });
  ['btn-seq-stop', 'mob-btn-stop'].forEach(id => {
    const el = document.getElementById(id); if (el) el.style.display = playing ? '' : 'none';
  });
};

// ── MOBILE HORIZONTAL SLIDES ─────────────────────────────────────────
function isMobileSlides() { return window.innerWidth <= 768; }

// Slide order on mobile: canvas | seq | drums  (3 slides — scale replaced by strip)
const SLIDE_ELS = () => [
  document.querySelector('.main-layout'),
  document.getElementById('seq-wrap'),
  document.getElementById('drum-wrap'),
];

function scrollToSlide(idx) {
  const outer = document.getElementById('outer-wrap');
  const els = SLIDE_ELS();
  const target = els[idx];
  if (!target || !outer) return;
  outer.scrollTo({ left: target.offsetLeft, behavior: 'smooth' });
}

// Nav dots click
document.querySelectorAll('.slide-dot').forEach(dot => {
  dot.addEventListener('click', () => scrollToSlide(parseInt(dot.dataset.slide)));
});

// Init mobile slides
(function initMobileSlides() {
  if (!isMobileSlides()) return;

  // ── iOS fix: move fixed-overlay panels OUT of the scroll container ──
  // Safari treats position:fixed inside overflow:scroll as position:absolute.
  // Moving them to <body> makes them truly viewport-fixed.
  const strip = document.getElementById('mobile-scale-strip');
  ['mixer-wrap', 'synth-wrap', 'fretboard-wrap'].forEach(id => {
    const el = document.getElementById(id);
    if (el && strip) document.body.insertBefore(el, strip);
  });
  // Initialise CSS variable used to position fixed panels above the strip
  document.body.style.setProperty('--strip-h', '52px');

  // ── FABs ─────────────────────────────────────────────────────────────
  function closePanelOverlay(wrapId) {
    const wrap = document.getElementById(wrapId);
    if (!wrap) return;
    wrap.classList.remove('open');
    if (wrapId === 'mixer-wrap') {
      document.getElementById('btn-mixer')?.classList.remove('active-mixer');
      document.body.classList.remove('mixer-open');
    } else {
      document.getElementById('btn-synth')?.classList.remove('active-synth');
    }
  }

  function openPanelOverlay(wrapId) {
    const wrap = document.getElementById(wrapId);
    if (!wrap) return;
    wrap.classList.add('open');
    if (wrapId === 'mixer-wrap') {
      document.getElementById('btn-mixer')?.classList.add('active-mixer');
      document.body.classList.add('mixer-open');
    } else {
      document.getElementById('btn-synth')?.classList.add('active-synth');
    }
  }

  // Inject handle + header into each panel's synth-panel div
  [
    { wrapId: 'mixer-wrap', label: '<svg class="hdr-icon" style="width:1.1em;height:1.1em;margin-right:4px;fill:currentColor"><use href="simple-white-icons.svg#icon-mixer"></use></svg>Mixer',   color: '#60a5fa' },
    { wrapId: 'synth-wrap', label: '<svg class="hdr-icon" style="width:1.1em;height:1.1em;margin-right:4px;fill:currentColor"><use href="simple-white-icons.svg#icon-synth"></use></svg>Synth',   color: '#f59e0b' },
  ].forEach(({ wrapId, label, color }) => {
    const panel = document.querySelector(`#${wrapId} .synth-panel`);
    if (!panel) return;

    const handle = document.createElement('div');
    handle.className = 'mob-panel-handle';

    const hdr = document.createElement('div');
    hdr.className = 'mob-panel-hdr';
    hdr.innerHTML = `
      <span class="mob-panel-hdr-title" style="color:${color}">${label}</span>
      <button class="mob-panel-close" aria-label="Fermer">✕</button>
    `;
    hdr.querySelector('.mob-panel-close').addEventListener('click', () => closePanelOverlay(wrapId));

    panel.prepend(hdr);
    panel.prepend(handle);

    // Close when tapping the dark backdrop (not the sheet itself)
    document.getElementById(wrapId).addEventListener('click', e => {
      if (e.target === document.getElementById(wrapId)) closePanelOverlay(wrapId);
    });
  });

  // Create FAB buttons
  const fabMixer = document.createElement('button');
  fabMixer.id = 'mob-fab-mixer';
  fabMixer.className = 'mob-fab';
  fabMixer.innerHTML = '<svg class="hdr-icon" style="width:1.25em;height:1.25em"><use href="simple-white-icons.svg#icon-mixer"></use></svg>';
  fabMixer.setAttribute('aria-label', 'Mixer');

  const fabSynth = document.createElement('button');
  fabSynth.id = 'mob-fab-synth';
  fabSynth.className = 'mob-fab';
  fabSynth.innerHTML = '<svg class="hdr-icon" style="width:1.25em;height:1.25em"><use href="simple-white-icons.svg#icon-synth"></use></svg>';
  fabSynth.setAttribute('aria-label', 'Synth');

  document.body.appendChild(fabMixer);
  document.body.appendChild(fabSynth);

  fabMixer.addEventListener('click', () => {
    const isOpen = document.getElementById('mixer-wrap').classList.contains('open');
    isOpen ? closePanelOverlay('mixer-wrap') : openPanelOverlay('mixer-wrap');
  });
  fabSynth.addEventListener('click', () => {
    const isOpen = document.getElementById('synth-wrap').classList.contains('open');
    isOpen ? closePanelOverlay('synth-wrap') : openPanelOverlay('synth-wrap');
  });

  loadDrumSamples(() => drawDrumMachine());

  const outer = document.getElementById('outer-wrap');
  const dots  = document.querySelectorAll('.slide-dot');

  const obs = new IntersectionObserver(entries => {
    entries.forEach(entry => {
      if (!entry.isIntersecting) return;
      const idx = SLIDE_ELS().indexOf(entry.target);
      if (idx < 0) return;
      dots.forEach((d, i) => d.classList.toggle('active', i === idx));
      document.getElementById('btn-seq').classList.toggle('active-seq',   idx === 1);
      document.getElementById('btn-drums').classList.toggle('active-drums', idx === 2);
      // Scale strip: visible on canvas (0) + seq (1), hidden on drums (2)
      const showStrip = idx !== 2;
      if (strip) strip.style.display = showStrip ? 'flex' : 'none';
      document.body.style.setProperty('--strip-h', showStrip ? '52px' : '0px');
      if (idx === 0) setTimeout(resize, 60);
    });
  }, { root: outer, threshold: 0.5 });

  setTimeout(() => {
    SLIDE_ELS().forEach(el => { if (el) obs.observe(el); });
    drawSequencer();
    drawDrumMachine();
    resize();
  }, 80);

  // ── Mobile compact scale strip ──────────────────────────────────
  const mobTempSel = document.getElementById('mob-temp-sel');
  Object.entries(TEMPERAMENTS).forEach(([k, v]) => {
    const opt = document.createElement('option');
    opt.value = k; opt.textContent = v.name.replace('Equal (12-TET)','Equal').replace('Just Intonation (5-limit)','Just').replace('Pythagorean','Pythag.').replace('Meantone (¼-comma)','Meantone').replace('Werckmeister III','Werkm. III');
    if (k === S.temp) opt.selected = true;
    mobTempSel.appendChild(opt);
  });
  mobTempSel.addEventListener('change', function() {
    S.temp = this.value;
    const dt = document.getElementById('sel-temperament');
    if (dt) dt.value = this.value;
    document.getElementById('temp-desc').textContent = TEMPERAMENTS[S.temp].desc;
    updateInfo(); draw(); drawFretboard();
  });

  const mobFamSel = document.getElementById('mob-family-sel');
  Object.entries(SCALE_FAMILIES).forEach(([k, v]) => {
    const opt = document.createElement('option');
    const shortName = v.name.replace('Western Modes','Western').replace('Pentatonic & Blues','Penta.').replace('Arabic Maqamat','Arabic').replace('Indian Ragas','Indian');
    opt.value = k; opt.textContent = shortName;
    if (k === S.family) opt.selected = true;
    mobFamSel.appendChild(opt);
  });

  function populateMobScale() {
    const sel = document.getElementById('mob-scale-sel');
    sel.innerHTML = '';
    Object.keys(SCALE_FAMILIES[S.family]?.scales || {}).forEach(name => {
      const opt = document.createElement('option');
      opt.value = name; opt.textContent = name;
      if (name === S.scaleName) opt.selected = true;
      sel.appendChild(opt);
    });
  }
  populateMobScale();

  function updateMobRoot() {
    document.getElementById('mob-root-lbl').textContent = CHROMATIC[S.root];
  }
  updateMobRoot();

  document.getElementById('mob-root-prev').addEventListener('click', () => {
    S.root = (S.root + 11) % 12;
    updateMobRoot(); refreshNoteGrid('root-grid','root');
    updateInfo(); draw(); if (S.fretboardOpen) drawFretboard();
  });
  document.getElementById('mob-root-next').addEventListener('click', () => {
    S.root = (S.root + 1) % 12;
    updateMobRoot(); refreshNoteGrid('root-grid','root');
    updateInfo(); draw(); if (S.fretboardOpen) drawFretboard();
  });
  mobFamSel.addEventListener('change', function() {
    S.family = this.value;
    const mainFam = document.getElementById('sel-family');
    if (mainFam) mainFam.value = this.value;
    buildScaleSelect();
    populateMobScale();
    updateInfo(); draw();
  });
  document.getElementById('mob-scale-sel').addEventListener('change', function() {
    S.scaleName = this.value;
    const mainSc = document.getElementById('sel-scale');
    if (mainSc) mainSc.value = this.value;
    updateInfo(); draw();
  });

  // Keep strip in sync when desktop panel changes
  document.getElementById('sel-scale').addEventListener('change', () => {
    const ms = document.getElementById('mob-scale-sel');
    if (ms && ms.value !== S.scaleName) ms.value = S.scaleName;
  });

  // Mobile play/stop via shared syncPlayUI
  document.getElementById('mob-btn-play').addEventListener('click', () => seqEngine.play());
  document.getElementById('mob-btn-stop').addEventListener('click', () => seqEngine.stop());

  // Visual canvas controls are initialized globally below (initSynthVisualControls)
})();

// ── SYNTH VISUAL CONTROLS (desktop + mobile) ──────────────────────────
(function initSynthVisualControls() {
    const A3 = '#f59e0b';

    function valLabel(ctx, text, w, h, color) {
      ctx.fillStyle = color || 'rgba(245,158,11,0.82)';
      ctx.font = `bold ${Math.round(h * 0.26)}px monospace`;
      ctx.textAlign = 'right';
      ctx.textBaseline = 'bottom';
      ctx.fillText(text, w - 4, h - 3);
    }

    function drawAttack(ctx, w, h, t) {
      const peakX = w * 0.06 + t * w * 0.76;
      const baseY = h * 0.84, topY = h * 0.1;
      ctx.beginPath();
      ctx.moveTo(0, baseY); ctx.lineTo(peakX, topY); ctx.lineTo(w, topY);
      ctx.lineTo(w, baseY); ctx.closePath();
      ctx.fillStyle = 'rgba(245,158,11,0.07)'; ctx.fill();
      ctx.beginPath();
      ctx.moveTo(0, baseY); ctx.lineTo(peakX, topY); ctx.lineTo(w, topY);
      ctx.strokeStyle = A3; ctx.lineWidth = 2; ctx.stroke();
    }

    function drawDecay(ctx, w, h, t) {
      const sy = h * 0.1, ey = h * 0.72;
      ctx.beginPath();
      for (let i = 0; i <= 60; i++) {
        const x = (i / 60) * w;
        const decay = Math.exp(-( i / 60) * (5 - t * 4.3));
        const y = sy + (ey - sy) * (1 - decay);
        i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
      }
      ctx.strokeStyle = A3; ctx.lineWidth = 2; ctx.stroke();
    }

    function drawFilter(ctx, w, h, t) {
      const cutX = w * 0.08 + t * w * 0.8;
      const topY = h * 0.14, botY = h * 0.82;
      ctx.beginPath();
      ctx.moveTo(0, topY); ctx.lineTo(cutX, topY);
      ctx.bezierCurveTo(cutX + w * 0.09, topY, cutX + w * 0.09, botY, cutX + w * 0.2, botY);
      ctx.lineTo(w, botY);
      ctx.strokeStyle = '#fb923c'; ctx.lineWidth = 2; ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(cutX, topY - 3); ctx.lineTo(cutX, botY + 3);
      ctx.strokeStyle = 'rgba(251,146,60,0.25)'; ctx.lineWidth = 1;
      ctx.setLineDash([3, 3]); ctx.stroke(); ctx.setLineDash([]);
    }

    function drawReso(ctx, w, h, t) {
      const baseY = h * 0.76, cx = w * 0.5;
      const ph = t * h * 0.6;
      const spread = Math.max(10, w * 0.28 * (1 - t * 0.75));
      ctx.beginPath(); ctx.moveTo(0, baseY); ctx.lineTo(w, baseY);
      ctx.strokeStyle = 'rgba(251,146,60,0.22)'; ctx.lineWidth = 1; ctx.stroke();
      if (ph > 1) {
        ctx.beginPath();
        ctx.moveTo(0, baseY);
        ctx.bezierCurveTo(cx - spread, baseY, cx - spread / 3, baseY - ph, cx, baseY - ph);
        ctx.bezierCurveTo(cx + spread / 3, baseY - ph, cx + spread, baseY, w, baseY);
        ctx.strokeStyle = '#fb923c'; ctx.lineWidth = 2; ctx.stroke();
      }
    }

    function drawVibRate(ctx, w, h, t) {
      const cycles = 1 + t * 5.5, mid = h * 0.5, amp = h * 0.3;
      ctx.beginPath();
      for (let x = 0; x <= w; x++) {
        const y = mid + Math.sin((x / w) * cycles * Math.PI * 2) * amp;
        x === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
      }
      ctx.strokeStyle = A3; ctx.lineWidth = 2; ctx.stroke();
    }

    function drawVibDepth(ctx, w, h, t) {
      const amp = t * h * 0.4, mid = h * 0.5;
      ctx.beginPath();
      for (let x = 0; x <= w; x++) {
        const y = mid + Math.sin((x / w) * 3 * Math.PI * 2) * amp;
        x === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
      }
      ctx.strokeStyle = amp > 1 ? A3 : 'rgba(245,158,11,0.28)';
      ctx.lineWidth = 2; ctx.stroke();
      if (amp < 2) {
        ctx.beginPath(); ctx.moveTo(0, mid); ctx.lineTo(w, mid);
        ctx.strokeStyle = 'rgba(245,158,11,0.28)'; ctx.lineWidth = 1; ctx.stroke();
      }
    }

    function drawSustain(ctx, w, h, t) {
      // ADSR envelope shape with sustain level shown
      const susY = h * 0.12 + (1 - t) * h * 0.65;
      const atkX = w * 0.18, decX = w * 0.38, relX = w * 0.85;
      ctx.beginPath();
      ctx.moveTo(0, h * 0.9);
      ctx.lineTo(atkX, h * 0.1);
      ctx.lineTo(decX, susY);
      ctx.lineTo(relX, susY);
      ctx.lineTo(w, h * 0.9);
      ctx.strokeStyle = A3; ctx.lineWidth = 2; ctx.stroke();
      // Sustain level dashed line
      ctx.beginPath();
      ctx.moveTo(decX, susY); ctx.lineTo(relX, susY);
      ctx.strokeStyle = 'rgba(245,158,11,0.3)'; ctx.lineWidth = 1;
      ctx.setLineDash([3,3]); ctx.stroke(); ctx.setLineDash([]);
    }

    function drawDetune(ctx, w, h, t) {
      // t=0.5 = center (0¢). Two sine waves offset in phase by detune amount
      const mid = h * 0.5, amp = h * 0.3, offset = (t - 0.5) * 2; // -1 to 1
      // Reference wave (gray)
      ctx.beginPath();
      for (let x = 0; x <= w; x++) {
        const y = mid + Math.sin((x / w) * 3 * Math.PI * 2) * amp;
        x === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
      }
      ctx.strokeStyle = 'rgba(245,158,11,0.2)'; ctx.lineWidth = 1; ctx.stroke();
      // Detuned wave (colored, shifted in phase)
      ctx.beginPath();
      const shift = offset * Math.PI * 0.6;
      for (let x = 0; x <= w; x++) {
        const y = mid + Math.sin((x / w) * 3 * Math.PI * 2 + shift) * amp;
        x === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
      }
      ctx.strokeStyle = Math.abs(offset) < 0.02 ? 'rgba(245,158,11,0.4)' : A3;
      ctx.lineWidth = 2; ctx.stroke();
      // Center marker
      ctx.beginPath(); ctx.moveTo(w/2, h*0.05); ctx.lineTo(w/2, h*0.95);
      ctx.strokeStyle = 'rgba(245,158,11,0.12)'; ctx.lineWidth = 1; ctx.stroke();
    }

    function drawHarmonics(ctx, w, h, t, count) {
      // Stack sine waves: more harmonics = more waves visible
      const n = Math.round(count);
      for (let i = 1; i <= n; i++) {
        const amp   = (h * 0.38) / i;
        const mid   = h * 0.5;
        const alpha = 0.9 - (i - 1) * 0.1;
        ctx.beginPath();
        for (let x = 0; x <= w; x++) {
          const y = mid + Math.sin((x / w) * i * 2 * Math.PI) * amp;
          x === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
        }
        ctx.strokeStyle = `rgba(167,139,250,${alpha.toFixed(2)})`;
        ctx.lineWidth = i === 1 ? 2 : 1; ctx.stroke();
      }
    }

    const DRAW = {
      'syn-attack':    (ctx, w, h, t, v) => { drawAttack(ctx, w, h, t);           valLabel(ctx, (v < 1000 ? v + 'ms' : (v/1000).toFixed(1) + 's'), w, h); },
      'syn-decay':     (ctx, w, h, t, v) => { drawDecay(ctx, w, h, t);            valLabel(ctx, (v/1000).toFixed(2) + 's', w, h); },
      'syn-filter':    (ctx, w, h, t, v) => { drawFilter(ctx, w, h, t);           valLabel(ctx, v >= 1000 ? (v/1000).toFixed(1) + 'kHz' : v + 'Hz', w, h, 'rgba(251,146,60,0.85)'); },
      'syn-res':       (ctx, w, h, t, v) => { drawReso(ctx, w, h, t);             valLabel(ctx, v.toFixed(1), w, h, 'rgba(251,146,60,0.85)'); },
      'syn-vib-rate':  (ctx, w, h, t, v) => { drawVibRate(ctx, w, h, t);          valLabel(ctx, v.toFixed(1) + 'Hz', w, h); },
      'syn-vib-depth': (ctx, w, h, t, v) => { drawVibDepth(ctx, w, h, t);         valLabel(ctx, Math.round(t * 100) + '%', w, h); },
      'syn-sustain':   (ctx, w, h, t, v) => { drawSustain(ctx, w, h, t);          valLabel(ctx, v + '%', w, h); },
      'syn-detune':    (ctx, w, h, t, v) => { drawDetune(ctx, w, h, t);           valLabel(ctx, v + '¢', w, h); },
      'syn-harmonics': (ctx, w, h, t, v) => { drawHarmonics(ctx, w, h, t, v);    valLabel(ctx, Math.round(v) + ' harm.', w, h, 'rgba(167,139,250,0.85)'); },
    };

    const allCvs = [];

    function paint(cvs, slider, fn) {
      if (!cvs.width) return;
      const ctx = cvs.getContext('2d');
      ctx.clearRect(0, 0, cvs.width, cvs.height);
      const v = parseFloat(slider.value);
      const t = (v - parseFloat(slider.min)) / (parseFloat(slider.max) - parseFloat(slider.min));
      fn(ctx, cvs.width, cvs.height, t, v);
    }

    function redrawAll() {
      allCvs.forEach(({ cvs, slider, fn }) => {
        const rect = cvs.getBoundingClientRect();
        if (rect.width > 0) cvs.width = Math.round(rect.width); // size once on open
        paint(cvs, slider, fn);
      });
    }

    // Redraw when synth overlay opens (after transition)
    document.getElementById('synth-wrap')?.addEventListener('transitionend', () => {
      if (document.getElementById('synth-wrap').classList.contains('open'))
        requestAnimationFrame(redrawAll);
    });

    Object.keys(DRAW).forEach(id => {
      const slider = document.getElementById(id);
      if (!slider) return;
      const group = slider.closest('.syn-group');
      if (!group) return;

      // Hide original slider and value display
      slider.style.display = 'none';
      const valSpan = group.querySelector('.syn-val');
      if (valSpan) valSpan.style.display = 'none';

      const cvs = document.createElement('canvas');
      cvs.className = 'vis-ctrl';
      cvs.height = 50;
      slider.parentNode.insertBefore(cvs, slider);

      const fn = DRAW[id];
      allCvs.push({ cvs, slider, fn });

      // During drag: paint only, never resize (width locked after first redrawAll)
      function redraw() { paint(cvs, slider, fn); }

      slider.addEventListener('input', redraw);

      // Drag interaction
      let startX, startVal;
      function onStart(x) { startX = x; startVal = parseFloat(slider.value); }
      function onMove(x) {
        const dx = x - startX;
        const range = parseFloat(slider.max) - parseFloat(slider.min);
        const step = parseFloat(slider.step) || 1;
        let nv = startVal + (dx / cvs.width) * range;
        nv = Math.round(nv / step) * step;
        nv = Math.max(parseFloat(slider.min), Math.min(parseFloat(slider.max), nv));
        slider.value = nv;
        slider.dispatchEvent(new Event('input', { bubbles: true }));
        redraw();
      }

      cvs.addEventListener('touchstart', e => { onStart(e.touches[0].clientX); e.preventDefault(); }, { passive: false });
      cvs.addEventListener('touchmove',  e => { onMove(e.touches[0].clientX);  e.preventDefault(); }, { passive: false });

      let dragging = false;
      cvs.addEventListener('mousedown', e => { dragging = true; onStart(e.clientX); e.preventDefault(); });
      window.addEventListener('mousemove', e => { if (dragging) onMove(e.clientX); });
      window.addEventListener('mouseup', () => { dragging = false; });
    });

    // Desktop: also trigger redraw on btn-synth click
    document.getElementById('btn-synth')?.addEventListener('click', () => {
      requestAnimationFrame(() => requestAnimationFrame(redrawAll));
    });
})();

// ── DEFAULT SCALE ON FIRST MIDI PLAY ────────────────────────────────
function ensureDefaultScale() {
  if (localStorage.getItem('midiPlayedOnce')) return;
  localStorage.setItem('midiPlayedOnce', '1');
  // Set equal temperament, western family, Chromatic scale, root C
  S.root = 0;
  S.temp = 'equal';
  S.family = 'western';
  S.scaleName = 'Chromatic';
  const selTemp = document.getElementById('sel-temperament');
  const selFam  = document.getElementById('sel-family');
  const selSc   = document.getElementById('sel-scale');
  if (selTemp) selTemp.value = 'equal';
  if (selFam)  { selFam.value = 'western'; buildScaleSelect(); }
  if (selSc)   selSc.value = 'Chromatic';
  document.getElementById('temp-desc').textContent = TEMPERAMENTS['equal'].desc;
  // Deselect all root buttons, select C
  document.querySelectorAll('#root-grid .note-btn').forEach((b, i) => b.classList.toggle('active', i === 0));
  updateInfo(); draw(); drawFretboard();
}

// Patch MIDI play button to run default scale logic first
const _origMidiPlayEl = document.getElementById('btn-midi-play');
_origMidiPlayEl.addEventListener('click', ensureDefaultScale, { capture: true });

// ── ONBOARDING TOUR ──────────────────────────────────────────────────
(function initTour() {
  if (localStorage.getItem('seenTour_v2')) return;

  // ── Step 1: Sensei welcome overlay ──
  const overlay = document.createElement('div');
  overlay.id = 'tour-overlay';
  overlay.innerHTML = `
    <div class="tour-modal">
      <div class="tour-sensei">🎎</div>
      <h2>Welcome, young apprentice</h2>
      <p>I am your guide to the infinite world of music theory.<br>
         Equal temperament, ancient maqamat, microtonal scales —<br>
         all await your ears.<br><br>
         Let us begin with a master of counterpoint.</p>
      <button class="tour-cta" id="tour-begin-btn">Begin the journey →</button>
    </div>`;
  document.body.appendChild(overlay);

  // ── Step 2: Tooltip pointing at MIDI play button ──
  const tooltip = document.createElement('div');
  tooltip.id = 'tour-tooltip';
  tooltip.style.display = 'none';
  tooltip.innerHTML = `
    <div class="tour-arrow-up"></div>
    <div class="tour-bubble">
      <span style="display:flex;align-items:center;gap:4px;"><svg class="hdr-icon" style="width:0.9em;height:0.9em;fill:currentColor"><use href="simple-white-icons.svg#icon-play"></use></svg> Press <strong>Play Bach</strong> to begin</span>
      <button class="tour-close-x" id="tour-tip-close">✕</button>
    </div>`;
  document.body.appendChild(tooltip);

  // ── Step 3: Scale hint toast ──
  const hint = document.createElement('div');
  hint.id = 'tour-hint';
  hint.style.display = 'none';
  hint.innerHTML = `<span>Now try changing the scale ↑</span>
    <button class="tour-close-x" id="tour-hint-close">✕</button>`;
  document.body.appendChild(hint);

  function positionTooltip() {
    const playBtn = document.getElementById('btn-midi-play');
    if (!playBtn) return;
    const r = playBtn.getBoundingClientRect();
    tooltip.style.left = Math.max(4, r.left - 4) + 'px';
    tooltip.style.top  = (r.bottom + 5) + 'px';
  }

  document.getElementById('tour-begin-btn').addEventListener('click', () => {
    overlay.style.display = 'none';
    positionTooltip();
    tooltip.style.display = 'block';
    // Pulse the play button to draw attention
    const pb = document.getElementById('btn-midi-play');
    pb.style.animation = 'tourPulse 1.2s ease infinite';
  });

  document.getElementById('tour-tip-close').addEventListener('click', () => {
    tooltip.style.display = 'none';
    document.getElementById('btn-midi-play').style.animation = '';
    localStorage.setItem('seenTour_v2', '1');
  });

  // When MIDI starts playing (during tour), show scale hint
  document.getElementById('btn-midi-play').addEventListener('click', () => {
    if (tooltip.style.display !== 'none') {
      tooltip.style.display = 'none';
      document.getElementById('btn-midi-play').style.animation = '';
      setTimeout(() => { hint.style.display = 'flex'; }, 1800);
    }
  });

  document.getElementById('tour-hint-close').addEventListener('click', () => {
    hint.style.display = 'none';
    localStorage.setItem('seenTour_v2', '1');
  });
})();

// ═══════════════════════════════════════════════════════════════════
// CROSS-DEVICE SYNC
// ═══════════════════════════════════════════════════════════════════

function syncGetFullState() {
  return {
    bpm:         SEQ.bpm,
    rhythmKey:   SEQ.rhythmKey,
    gate:        SEQ.gate,
    loopLen:     SEQ.loopLen,
    grid:        { ...SEQ.grid },
    drumGrid:    { ...DRUM_GRID },
    drumLoopLen,
  };
}

function syncApplyFullState(msg) {
  if (msg.bpm         !== undefined) SEQ.bpm       = msg.bpm;
  if (msg.rhythmKey   !== undefined) SEQ.rhythmKey  = msg.rhythmKey;
  if (msg.gate        !== undefined) SEQ.gate       = msg.gate;
  if (msg.loopLen     !== undefined) SEQ.loopLen    = msg.loopLen;
  if (msg.drumLoopLen !== undefined) drumLoopLen    = msg.drumLoopLen;
  if (msg.grid) SEQ.grid = { ...msg.grid };
  if (msg.drumGrid) {
    Object.keys(DRUM_GRID).forEach(k => delete DRUM_GRID[k]);
    Object.assign(DRUM_GRID, msg.drumGrid);
  }
  syncUpdateUI(msg);
}

function syncUpdateUI(msg) {
  if (msg.bpm !== undefined) {
    const sl = document.getElementById('seq-bpm');
    if (sl) sl.value = msg.bpm;
    const vl = document.getElementById('seq-bpm-val');
    if (vl) vl.textContent = msg.bpm;
  }
  if (msg.rhythmKey !== undefined) {
    const sel = document.getElementById('seq-rhythm');
    if (sel) sel.value = msg.rhythmKey;
    const loopSl = document.getElementById('seq-loop-len');
    if (loopSl) loopSl.max = seqSteps();
  }
  if (msg.loopLen !== undefined) {
    const sl = document.getElementById('seq-loop-len');
    if (sl) sl.value = msg.loopLen;
    const vl = document.getElementById('seq-loop-val');
    if (vl) vl.textContent = msg.loopLen;
  }
  if (msg.gate !== undefined) {
    const pct = Math.round(msg.gate * 100);
    const sl = document.getElementById('seq-gate');
    if (sl) sl.value = pct;
    const vl = document.getElementById('seq-gate-val');
    if (vl) vl.textContent = pct + '%';
  }
  if (msg.drumLoopLen !== undefined) {
    const sl = document.getElementById('drum-loop-len');
    if (sl) { sl.max = seqSteps(); sl.value = msg.drumLoopLen; }
    const vl = document.getElementById('drum-loop-val');
    if (vl) vl.textContent = msg.drumLoopLen;
  }
}

function syncHandleMessage(msg) {
  switch (msg.type) {

    case 'PLAY':
      peerEpochMs = msg.epochMs;
      if (msg.masterBpm !== undefined) applyPeerBpm(msg.masterBpm);
      syncApplyFullState(msg);
      if (seqEngine.playing) {
        epochMs = msg.epochMs;
        seqEngine.rebase(true);
      } else {
        seqEngine.play(msg.epochMs);
      }
      drawSequencer();
      drawDrumMachine();
      break;

    case 'JOINED':
      // A peer joined our session — just record their epoch, don't restart
      peerEpochMs = msg.epochMs;
      break;

    case 'STOP':
      peerEpochMs = null;
      seqEngine.stop(true);
      break;

    case 'REBASE':
      peerEpochMs = msg.epochMs;
      if (msg.masterBpm !== undefined) applyPeerBpm(msg.masterBpm);
      if (msg.rhythmKey !== undefined) SEQ.rhythmKey = msg.rhythmKey;
      if (msg.loopLen   !== undefined) SEQ.loopLen   = msg.loopLen;
      syncUpdateUI(msg);
      if (seqEngine.playing) { epochMs = msg.epochMs; seqEngine.rebase(true); }
      drawSequencer();
      break;

    case 'GRID_SET':
      if (msg.val) SEQ.grid[msg.key] = true;
      else         delete SEQ.grid[msg.key];
      drawSequencer();
      break;

    case 'DRUM_SET':
      if (msg.val) DRUM_GRID[msg.key] = true;
      else         delete DRUM_GRID[msg.key];
      drawDrumMachine();
      break;

    case 'SEQ_PARAM':
      if (msg.masterBpm   !== undefined) applyPeerBpm(msg.masterBpm);
      if (msg.rhythmKey   !== undefined) SEQ.rhythmKey  = msg.rhythmKey;
      if (msg.gate        !== undefined) SEQ.gate        = msg.gate;
      if (msg.loopLen     !== undefined) SEQ.loopLen     = msg.loopLen;
      if (msg.drumLoopLen !== undefined) drumLoopLen     = msg.drumLoopLen;
      syncUpdateUI(msg);
      if (seqEngine.playing) seqEngine.rebase(true);
      drawSequencer();
      drawDrumMachine();
      break;

    case 'PEER_JOINED':
      // A new peer connected — push current state to them
      if (seqEngine.playing) {
        syncSend({ type: 'PLAY', epochMs, ...syncGetFullState() });
      } else {
        syncSend({ type: 'FULL_STATE', playing: false, ...syncGetFullState() });
      }
      break;

    case 'FULL_STATE':
      // Received on join from a peer that isn't playing
      syncApplyFullState(msg);
      drawSequencer();
      drawDrumMachine();
      break;
  }
}

// ── Boot: connect if ?sync=ws://host:port is in the URL ─────────────
(function initSync() {
  const params    = new URLSearchParams(location.search);
  const serverUrl = params.get('sync');
  if (!serverUrl) return;

  // Status badge
  const badge = document.createElement('div');
  badge.style.cssText = 'position:fixed;top:8px;right:12px;font-size:11px;'
    + 'padding:2px 8px;border-radius:10px;background:#1e293b;color:#94a3b8;'
    + 'font-family:monospace;z-index:9999;pointer-events:none;';
  badge.textContent = '● sync: connecting…';
  document.body.appendChild(badge);

  // Tempo ratio UI — injected below the BPM slider when sync is active
  const bpmGroup = document.getElementById('seq-bpm')?.closest('.syn-group') ??
                   document.getElementById('seq-bpm')?.parentElement;
  if (bpmGroup) {
    const ratioRow = document.createElement('div');
    ratioRow.style.cssText = 'display:flex;gap:4px;margin-top:4px;align-items:center;';

    const label = document.createElement('span');
    label.textContent = 'ratio:';
    label.style.cssText = 'font-size:11px;color:#94a3b8;font-family:monospace;margin-right:2px;';
    ratioRow.appendChild(label);

    const RATIOS = [
      { label: '÷3', val: 1/3 },
      { label: '÷2', val: 0.5 },
      { label: '×1', val: 1   },
      { label: '×2', val: 2   },
      { label: '×3', val: 3   },
    ];

    RATIOS.forEach(({ label: lbl, val }) => {
      const btn = document.createElement('button');
      btn.textContent = lbl;
      btn.dataset.ratio = val;
      btn.style.cssText = 'font-size:11px;padding:1px 7px;border-radius:6px;border:1px solid #334155;'
        + 'background:#1e293b;color:#94a3b8;cursor:pointer;font-family:monospace;';
      if (val === 1) { btn.style.background = '#0f172a'; btn.style.color = '#4ade80'; btn.style.borderColor = '#4ade80'; }

      btn.addEventListener('click', () => {
        syncTempoRatio = val;
        // Highlight active
        ratioRow.querySelectorAll('button').forEach(b => {
          b.style.background   = '#1e293b';
          b.style.color        = '#94a3b8';
          b.style.borderColor  = '#334155';
        });
        btn.style.background  = '#0f172a';
        btn.style.color       = '#4ade80';
        btn.style.borderColor = '#4ade80';
        // Re-apply master BPM with new ratio
        applyPeerBpm(masterBpm);
      });

      ratioRow.appendChild(btn);
    });

    bpmGroup.appendChild(ratioRow);
  }

  Sync.connect(
    serverUrl,
    syncHandleMessage,
    () => { badge.textContent = '● sync: live';           badge.style.color = '#4ade80'; },
    () => { badge.textContent = '● sync: reconnecting…';  badge.style.color = '#f87171'; },
    // When NTP offset updates, re-anchor audio scheduling to the corrected clock
    (_newOffset) => {
      if (seqEngine.playing && epochMs !== null && !seqEngine._barJoining) {
        seqEngine._corrTick = 49; // trigger correction on very next tick
      }
    },
  );
})();

